  --ink-faint:rgba(22, 32, 46, .34);
  --bilbao: #4D8ABB;
  --espiritu: #5FB3DC;
  --herencia: #374C69;
  --pop: #F1C400;
  --glass: rgba(255, 255, 255, .52);
  --glass-brd:rgba(255, 255, 255, .72);
  --glass-sh: rgba(40, 70, 110, .12);
  --card: rgba(255, 255, 255, .62);
  --line: rgba(55, 76, 105, .14);
