  --bilbao: #7DC6E5;
  --espiritu: #A9E0F5;
  --herencia: #9FB6D4;
  --pop: #F1C400;
  --glass: rgba(14, 32, 52, .46);
  --glass-brd:rgba(125, 198, 229, .20);
  --glass-sh: rgba(0, 0, 0, .45);
  --card: rgba(11, 28, 46, .55);
  --line: rgba(125, 198, 229, .16);
  --halo: rgba(125, 198, 229, .18);
}

/* ── ANIMATIONS ───────────────────────────────────────────── */
@keyframes lnd-floaty {
  0%, 100% {
    transform: translateY(0) rotate(0);
  }
  50% {
    transform: translateY(-18px) rotate(-1.5deg);
  }
}
@keyframes lnd-floaty2 {
  0%, 100% {
    transform: translateY(0) rotate(0);
  }
  50% {
    transform: translateY(-12px) rotate(2deg);
  }
}
@keyframes lnd-kenburns {
  0% {
    transform: scale(1.04) translate(0, 0);
  }
  100% {
    transform: scale(1.2) translate(-2%, -3%);
  }
}
@keyframes lnd-marquee {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}
@keyframes lnd-scroll {
  0% {
    transform: translateY(0);
    opacity: 1;
  }
  70% {
    transform: translateY(15px);
    opacity: 0;
  }
  100% {
    opacity: 0;
  }
}
@keyframes lnd-ping {
  0% {
    transform: scale(1);
    opacity: 0.55;
  }
  100% {
    transform: scale(2.7);
    opacity: 0;
  }
}
@keyframes lnd-poster-in {
  0% {
    opacity: 0;
    transform: translateY(28px) scale(0.96);
  }
  100% {
    opacity: 1;
    transform: none;
  }
}
@keyframes lnd-poster-kb {
  0% {
    transform: scale(1.06) translate(0, 0);
  }
  100% {
    transform: scale(1.14) translate(-1.5%, -2%);
  }
}
/* ── FOREST CANVAS ────────────────────────────────────────── */
.lnd-forest-canvas {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 0;
  pointer-events: none;
  transition: opacity 0.6s ease;
}

.lnd-forest-veil {
  position: fixed;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background: radial-gradient(135% 105% at 50% 2%, transparent 46%, var(--bg) 100%);
  transition: background 0.7s ease;
}

/* ── LANDING ROOT ─────────────────────────────────────────── */
.landing-root {
  position: relative;
  background: var(--bg);
  color: var(--ink);
  font-family: "Outfit", system-ui, sans-serif;
  overflow-x: clip;
  transition: background 0.7s ease, color 0.7s ease;
  /* All direct children above canvas */
}
.landing-root > * {
  position: relative;
  z-index: 10;
}
.landing-root > .lnd-forest-canvas,
.landing-root > .lnd-forest-veil {
  z-index: 0;
  position: fixed;
}
.landing-root > .lnd-theme-btn {
  z-index: 80;
}

/* ── HERO ─────────────────────────────────────────────────── */
.lnd-hero {
  position: relative;
  z-index: 10;
  min-height: 100svh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: clamp(80px, 12vw, 140px) clamp(20px, 5vw, 60px) clamp(60px, 8vw, 100px);
  text-align: center;
  overflow: hidden;
  /* En móvil/tablet el hero se apila (texto + poster), así que dejamos que
     crezca con el contenido en vez de forzar 100svh y recortar. El header
     fijo (80px) obliga a un padding-top mayor. */
}
@media (max-width: 899px) {
  .lnd-hero {
    min-height: auto;
    overflow: visible;
    padding-top: 116px;
    padding-bottom: 56px;
  }
}
.lnd-hero {
  /* Neblina anclada al borde de la pantalla: da contraste uniforme a TODO el
     texto (incluida la palabra de acento) y se desvanece hacia la imagen. */
}
.lnd-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  /* Niebla simétrica: densa en ambos bordes, despejada al centro */
  background: linear-gradient(90deg, rgba(var(--bg-rgb), 0.96) 0%, rgba(var(--bg-rgb), 0.82) 18%, rgba(var(--bg-rgb), 0.3) 38%, rgba(var(--bg-rgb), 0) 50%, rgba(var(--bg-rgb), 0.3) 62%, rgba(var(--bg-rgb), 0.82) 82%, rgba(var(--bg-rgb), 0.96) 100%);
  /* Fade vertical (arriba/abajo) para que la niebla no tenga un canto duro */
  -webkit-mask-image: linear-gradient(180deg, transparent 0%, #000 9%, #000 74%, transparent 100%);
  mask-image: linear-gradient(180deg, transparent 0%, #000 9%, #000 74%, transparent 100%);
}
@media (max-width: 899px) {
  .lnd-hero::before {
    /* En móvil (apilado) la niebla es simétrica en vertical */
    background: linear-gradient(180deg, rgba(var(--bg-rgb), 0.92) 0%, rgba(var(--bg-rgb), 0.3) 26%, rgba(var(--bg-rgb), 0) 50%, rgba(var(--bg-rgb), 0.3) 74%, rgba(var(--bg-rgb), 0.92) 100%);
    -webkit-mask-image: none;
    mask-image: none;
  }
}
.lnd-hero__grid {
  position: relative;
  z-index: 2;
  width: 100%;
  max-width: 1180px;
  display: grid;
  grid-template-columns: 1fr;
  align-items: center;
  gap: clamp(30px, 5vw, 60px);
}
@media (min-width: 900px) {
  .lnd-hero__grid {
    grid-template-columns: 1.02fr 0.98fr;
    align-items: stretch; /* ambas columnas comparten la misma altura */
  }
}
.lnd-hero__content {
  position: relative;
  z-index: 2;
  max-width: 620px;
  margin: 0 auto;
}
@media (min-width: 900px) {
  .lnd-hero__content {
    margin: 0;
    text-align: left;
  }
}
.lnd-hero__eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 2px;
  line-height: 1.6;
  text-transform: uppercase;
  color: var(--ink-soft);
  margin-bottom: 26px;
}
@media (max-width: 767px) {
  .lnd-hero__eyebrow {
    line-height: 1.35;
    margin-bottom: 18px;
  }
}
.lnd-hero__title {
  font-size: clamp(2.6rem, 5.6vw, 4.5rem);
  font-weight: 900;
  line-height: 1.05;
  letter-spacing: -0.04em;
  color: var(--ink);
  margin-top: 0;
  margin-bottom: 26px;
  /* Halo del color de fondo alrededor de las letras → más legible sobre el bosque */
  text-shadow: 0 2px 22px var(--bg);
  transition: opacity 0.45s ease, transform 0.45s ease;
  /* Altura FIJA (relativa al tamaño de fuente) para que las frases
     al rotar —sean de 2 o 3 líneas— no muevan el contenido inferior.
     El texto se centra verticalmente dentro de la caja reservada. */
  display: flex;
  align-items: center;
  justify-content: center;
  height: 2.5em;
}
@media (min-width: 900px) {
  .lnd-hero__title {
    justify-content: flex-start;
    height: 3.25em; /* reserva para las frases que ocupan 3 líneas en la columna */
  }
}
@media (max-width: 767px) {
  .lnd-hero__title {
    height: 3.2em;
  }
}
.lnd-hero__title-inner {
  display: block;
  text-align: center;
}
@media (min-width: 900px) {
  .lnd-hero__title-inner {
    text-align: left;
  }
}
.lnd-hero__hi {
  /* Azules profundos y saturados → nítido sobre el fondo pálido del bosque */
  background: linear-gradient(110deg, #1f5a94, #2f7cb8);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.lnd-hero {
  /* En modo oscuro se usan azules claros para que resalten sobre el fondo oscuro */
}
[data-theme=dark] .lnd-hero__hi {
  background: linear-gradient(110deg, var(--bilbao), var(--espiritu));
  -webkit-background-clip: text;
  background-clip: text;
}
.lnd-hero__sub {
  font-size: clamp(1rem, 1.8vw, 1.12rem);
  color: var(--ink-soft);
  max-width: 46ch;
  margin: 0 auto 40px;
  font-weight: 400;
  line-height: 1.7;
}
@media (min-width: 900px) {
  .lnd-hero__sub {
    margin-left: 0;
    margin-right: 0;
  }
}
@media (max-width: 767px) {
  .lnd-hero__sub {
    margin-bottom: 26px;
  }
}
.lnd-hero__ctas {
  display: flex;
  gap: 14px;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 40px;
}
@media (min-width: 900px) {
  .lnd-hero__ctas {
    justify-content: flex-start;
    margin-bottom: 0;
  }
}
.lnd-hero {
  /* ── POSTER / IMAGEN REAL DEL COLEGIO ── */
}
.lnd-hero__media {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: stretch;
  justify-content: center;
}
@media (max-width: 899px) {
  .lnd-hero__media {
    order: 2;
    width: 100%;
    max-width: 560px;
    margin: 0 auto;
  }
}
.lnd-hero__poster {
  position: relative;
  margin: 0;
  width: 100%;
  aspect-ratio: 4/3;
  border-radius: 26px;
  /* En desktop iguala la altura de la columna de contenido (sin proporción fija) */
}
@media (min-width: 900px) {
  .lnd-hero__poster {
    aspect-ratio: auto;
    height: 100%;
    min-height: 460px;
  }
}
.lnd-hero__poster {
  overflow: hidden;
  background: #0b1726;
  border: 1px solid var(--glass-brd);
  box-shadow: 0 44px 90px -42px rgba(8, 19, 32, 0.6);
  animation: lnd-poster-in 1s cubic-bezier(0.2, 0.8, 0.2, 1) both;
  /* Halo/anillo sutil que enmarca el poster como pieza intencional */
}
.lnd-hero__poster::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.12);
  pointer-events: none;
}
@media (max-width: 899px) {
  .lnd-hero__poster {
    aspect-ratio: 16/10;
  }
}
@media (max-width: 767px) {
  .lnd-hero__poster {
    aspect-ratio: 3/2;
    border-radius: 20px;
  }
}
.lnd-hero__slides {
  position: absolute;
  inset: 0;
  z-index: 1;
}
.lnd-hero__slide {
  position: absolute;
  inset: 0;
  opacity: 0;
  z-index: 0;
  /* Crossfade suave: la nueva imagen aparece ENCIMA de la anterior
     (que sigue opaca en .is-prev), evitando el parpadeo del fondo. */
  transition: opacity 1.1s ease;
}
.lnd-hero__slide.is-prev {
  opacity: 1;
  z-index: 1;
}
.lnd-hero__slide { /* saliente: permanece visible debajo */ }
.lnd-hero__slide.is-active {
  opacity: 1;
  z-index: 2;
}
.lnd-hero__slide { /* entrante: se funde por encima */ }
.lnd-hero__slide picture {
  position: absolute;
  inset: 0;
  display: block;
}
.lnd-hero__slide-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.lnd-hero {
  /* Ken Burns solo en la imagen activa */
}
.lnd-hero__slide.is-active .lnd-hero__slide-img {
  animation: lnd-poster-kb 20s ease-in-out infinite alternate;
}
@media (prefers-reduced-motion: reduce) {
  .lnd-hero__slide.is-active .lnd-hero__slide-img {
    animation: none;
  }
}
.lnd-hero__poster-badge {
  position: absolute;
  left: 16px;
  bottom: 16px;
  z-index: 3;
  display: flex;
  flex-direction: column;
  gap: 3px;
  margin: 0;
  padding: 10px 16px;
  border-radius: 14px;
  color: #fff;
  background: rgba(8, 19, 32, 0.42);
  border: 1px solid rgba(255, 255, 255, 0.18);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}
.lnd-hero__poster-badge strong {
  font-size: 1.15rem;
  font-weight: 900;
  letter-spacing: -0.02em;
  line-height: 1;
}
.lnd-hero__poster-badge span {
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.3px;
  color: rgba(255, 255, 255, 0.85);
}
.lnd-hero {
  /* Controles del carrusel (flechas, zoom, dots) — botón circular glassy */
}
.lnd-hero__nav, .lnd-hero__zoom {
  position: absolute;
  z-index: 5;
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  padding: 0;
  border-radius: 50%;
  color: #fff;
  background: rgba(8, 19, 32, 0.5);
  border: 1px solid rgba(255, 255, 255, 0.25);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  cursor: pointer;
  opacity: 0.82;
  transition: opacity 0.25s, transform 0.25s, background 0.25s;
}
.lnd-hero__nav svg, .lnd-hero__zoom svg {
  width: 20px;
  height: 20px;
}
.lnd-hero__nav:hover, .lnd-hero__zoom:hover {
  opacity: 1;
  background: var(--bilbao);
}
.lnd-hero__nav:focus-visible, .lnd-hero__zoom:focus-visible {
  opacity: 1;
  outline: 2px solid #fff;
  outline-offset: 2px;
}
.lnd-hero__nav {
  top: 50%;
  transform: translateY(-50%);
}
.lnd-hero__nav:hover {
  transform: translateY(-50%) scale(1.05);
}
.lnd-hero__nav--prev {
  left: 12px;
}
.lnd-hero__nav--next {
  right: 12px;
}
@media (max-width: 480px) {
  .lnd-hero__nav {
    width: 38px;
    height: 38px;
  }
}
.lnd-hero__zoom {
  top: 14px;
  right: 14px;
  cursor: zoom-in;
}
.lnd-hero__dots {
  position: absolute;
  z-index: 5;
  left: 50%;
  bottom: 16px;
  transform: translateX(-50%);
  display: flex;
  gap: 8px;
}
.lnd-hero__dots span {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.45);
  border: 1px solid rgba(255, 255, 255, 0.35);
  cursor: pointer;
  transition: background 0.25s, width 0.25s;
}
.lnd-hero__dots span.is-active {
  width: 22px;
  border-radius: 5px;
  background: #fff;
}
.lnd-hero__scroll {
  position: absolute;
  bottom: 32px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 3;
}
.lnd-hero__scroll-dot {
  display: block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--bilbao);
  animation: lnd-scroll 1.8s ease-in-out infinite;
}

/* ── LIGHTBOX (ampliar imágenes) ──────────────────────────── */
.lnd-lightbox {
  position: fixed;
  inset: 0;
  z-index: 2000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: clamp(16px, 4vw, 56px);
  background: rgba(6, 14, 24, 0.88);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.3s ease, visibility 0.3s;
}
.lnd-lightbox.is-open {
  opacity: 1;
  visibility: visible;
}
.lnd-lightbox__img {
  max-width: 100%;
  max-height: 100%;
  width: auto;
  height: auto;
  border-radius: 14px;
  box-shadow: 0 40px 120px -20px rgba(0, 0, 0, 0.7);
  transform: scale(0.96);
  transition: transform 0.3s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.lnd-lightbox.is-open .lnd-lightbox__img {
  transform: scale(1);
}
.lnd-lightbox__close {
  position: absolute;
  top: 18px;
  right: 18px;
  width: 46px;
  height: 46px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.28);
  background: rgba(255, 255, 255, 0.12);
  cursor: pointer;
  transition: background 0.2s;
  z-index: 2;
}
.lnd-lightbox__close::before, .lnd-lightbox__close::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 18px;
  height: 2px;
  background: #fff;
  border-radius: 2px;
}
.lnd-lightbox__close::before {
  transform: translate(-50%, -50%) rotate(45deg);
}
.lnd-lightbox__close::after {
  transform: translate(-50%, -50%) rotate(-45deg);
}
.lnd-lightbox__close:hover {
  background: rgba(255, 255, 255, 0.24);
}
.lnd-lightbox__close:focus-visible {
  outline: 2px solid #fff;
  outline-offset: 3px;
}
.lnd-lightbox__nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 2;
  display: grid;
  place-items: center;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.28);
  background: rgba(255, 255, 255, 0.12);
  color: #fff;
  cursor: pointer;
  transition: background 0.2s, transform 0.2s;
}
.lnd-lightbox__nav svg {
  width: 24px;
  height: 24px;
}
.lnd-lightbox__nav:hover {
  background: rgba(255, 255, 255, 0.24);
}
.lnd-lightbox__nav:focus-visible {
  outline: 2px solid #fff;
  outline-offset: 3px;
}
.lnd-lightbox__nav--prev {
  left: clamp(12px, 3vw, 32px);
}
.lnd-lightbox__nav--next {
  right: clamp(12px, 3vw, 32px);
}
.lnd-lightbox__nav--prev:hover {
  transform: translateY(-50%) scale(1.06);
}
.lnd-lightbox__nav--next:hover {
  transform: translateY(-50%) scale(1.06);
}
@media (max-width: 480px) {
  .lnd-lightbox__nav {
    width: 44px;
    height: 44px;
  }
}

.lnd-btn-hero {
