.lnd-level-card {
  position: relative;
  min-height: 380px;
  border-radius: 26px;
  overflow: hidden;
  border: 1px solid var(--glass-brd);
  box-shadow: 0 32px 70px -46px var(--glass-sh);
  text-decoration: none;
  display: block;
  background: #0b1726;
  transition: transform 0.5s cubic-bezier(0.2, 0.8, 0.2, 1), box-shadow 0.5s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.lnd-level-card:hover {
  transform: translateY(-8px);
  box-shadow: 0 48px 80px -36px rgba(77, 138, 187, 0.45), 0 0 0 2px rgba(77, 138, 187, 0.3);
}
.lnd-level-card {
  /* Barra de acento inferior */
}
.lnd-level-card::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--espiritu), var(--bilbao));
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.4s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.lnd-level-card:hover::after {
  transform: scaleX(1);
}
.lnd-level-card__bg {
  position: absolute;
  inset: 0;
}
.lnd-level-card__bg img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  animation: lnd-kenburns 22s ease-in-out infinite alternate;
  transition: transform 0.6s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.lnd-level-card:hover .lnd-level-card__bg img {
  transform: scale(1.08);
}
.lnd-level-card__overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(8, 19, 32, 0) 18%, rgba(8, 19, 32, 0.72) 65%, rgba(8, 19, 32, 0.92));
  transition: background 0.4s ease;
}
.lnd-level-card:hover .lnd-level-card__overlay {
  background: linear-gradient(180deg, rgba(8, 19, 32, 0.06) 10%, rgba(8, 19, 32, 0.78) 58%, rgba(8, 19, 32, 0.95));
}
.lnd-level-card__alex {
  position: absolute;
  right: 16px;
  top: 16px;
  width: 84px;
  filter: drop-shadow(0 10px 18px rgba(0, 0, 0, 0.45));
  opacity: 0.6;
  transform: translateY(0) scale(0.94);
  transition: opacity 0.4s ease, transform 0.4s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.lnd-level-card:hover .lnd-level-card__alex {
  opacity: 1;
  transform: translateY(-6px) scale(1);
}
.lnd-level-card__content {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  padding: 28px 28px 32px;
  color: #fff;
