}

/* ── DESCUBRE ─────────────────────────────────────────────── */
.lnd-descubre {
  position: relative;
  z-index: 10;
  padding: 50px clamp(18px, 5vw, 60px);
  background: linear-gradient(180deg, var(--bg) 0%, var(--bg2) 100%);
}
.lnd-descubre__header {
  max-width: var(--container-width);
  margin: 0 auto 40px;
  text-align: center;
}
.lnd-descubre__eyebrow {
  font-size: 0.78rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--bilbao);
}
.lnd-descubre__title {
  font-weight: 900;
  font-size: clamp(2rem, 4.6vw, 3.5rem);
  letter-spacing: -0.035em;
  margin-top: 10px;
  color: var(--ink);
}
.lnd-descubre__grid {
  max-width: var(--container-width);
  margin: 0 auto;
