.lnd-ex-card {
  position: relative;
  min-height: 380px;
  border-radius: 26px;
  text-decoration: none;
  border: 1px solid var(--glass-brd);
  box-shadow: 0 32px 70px -46px var(--glass-sh);
  display: block;
  background: #0b1726;
  overflow: hidden; /* clipa el zoom del __photo dentro de las esquinas redondeadas */
  transition: transform 0.45s cubic-bezier(0.2, 0.8, 0.2, 1), box-shadow 0.45s ease;
}
@media (max-width: 560px) {
  .lnd-ex-card {
    min-height: 300px;
  }
}
.lnd-ex-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 40px 80px -40px var(--glass-sh);
}
.lnd-ex-card__clip {
  position: absolute;
  inset: 0;
  border-radius: 26px;
  overflow: hidden;
}
.lnd-ex-card__photo {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.8s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.lnd-ex-card__overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(8, 19, 32, 0.1) 28%, rgba(8, 19, 32, 0.92));
}
.lnd-ex-card__tint {
  position: absolute;
  inset: 0;
  background: linear-gradient(160deg, rgba(77, 138, 187, 0.34), rgba(28, 56, 90, 0.62));
  opacity: 0;
  transition: opacity 0.5s;
}
.lnd-ex-card__alex {
  position: absolute;
  right: 14px;
  top: 14px;
  width: 96px;
  filter: drop-shadow(0 12px 22px rgba(0, 0, 0, 0.55));
  z-index: 3;
  opacity: 0;
  transform: translateY(26px) scale(0.7) rotate(-8deg);
  transition: all 0.55s cubic-bezier(0.2, 0.9, 0.3, 1.5);
}
.lnd-ex-card__body {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  padding: 28px 26px;
  color: #fff;
  z-index: 3;
}
.lnd-ex-card__num {
  font-family: monospace;
  font-size: 0.82rem;
  color: rgba(255, 255, 255, 0.72);
  font-weight: 600;
  display: block;
  margin-bottom: 7px;
}
.lnd-ex-card__bar {
  height: 3px;
  background: var(--espiritu);
  border-radius: 3px;
  margin-bottom: 13px;
  width: 0;
  transition: width 0.55s ease 0.05s;
}
.lnd-ex-card__title {
  font-weight: 900;
  font-size: 1.55rem;
  letter-spacing: -0.025em;
}
.lnd-ex-card__desc {
  font-size: 0.93rem;
  line-height: 1.55;
  color: rgba(255, 255, 255, 0.88);
  font-weight: 300;
  /* Reveal fluido con grid-rows (0fr → 1fr) en vez de max-height (evita el salto) */
  display: grid;
  grid-template-rows: 0fr;
  opacity: 0;
  transform: translateY(8px);
  transition: grid-template-rows 0.5s cubic-bezier(0.2, 0.8, 0.2, 1), opacity 0.45s ease, transform 0.5s ease, margin 0.5s ease;
  margin: 0;
}
.lnd-ex-card__desc > * {
  overflow: hidden;
  min-height: 0;
}
.lnd-ex-card__go {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 0.88rem;
  font-weight: 700;
  color: #fff;
  opacity: 0;
  transform: translateY(6px);
  transition: opacity 0.4s ease 0.15s, transform 0.4s ease 0.15s;
  /* Solo la flecha (último span) es el círculo; el texto "Conocer" queda intacto */
}
.lnd-ex-card__go > span:last-child {
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: var(--bilbao);
  flex: 0 0 auto;
}
.lnd-ex-card {
  /* ── Revelado en dispositivos con hover (desktop) + foco por teclado ── */
}
@media (hover: hover) {
  .lnd-ex-card:hover .lnd-ex-card__photo, .lnd-ex-card:focus-visible .lnd-ex-card__photo {
    transform: scale(1.1);
  }
  .lnd-ex-card:hover .lnd-ex-card__tint, .lnd-ex-card:focus-visible .lnd-ex-card__tint {
    opacity: 1;
  }
  .lnd-ex-card:hover .lnd-ex-card__alex, .lnd-ex-card:focus-visible .lnd-ex-card__alex {
    opacity: 1;
    transform: none;
  }
  .lnd-ex-card:hover .lnd-ex-card__bar, .lnd-ex-card:focus-visible .lnd-ex-card__bar {
    width: 48px;
  }
  .lnd-ex-card:hover .lnd-ex-card__desc, .lnd-ex-card:focus-visible .lnd-ex-card__desc {
    grid-template-rows: 1fr;
    opacity: 1;
    transform: none;
    margin: 12px 0 16px;
  }
  .lnd-ex-card:hover .lnd-ex-card__go, .lnd-ex-card:focus-visible .lnd-ex-card__go {
    opacity: 1;
    transform: none;
  }
}
.lnd-ex-card {
  /* ── En dispositivos táctiles (sin hover) el contenido siempre visible ── */
}
@media (hover: none) {
  .lnd-ex-card__tint {
    opacity: 1;
  }
  .lnd-ex-card__bar {
    width: 48px;
  }
  .lnd-ex-card__desc {
    grid-template-rows: 1fr;
    opacity: 1;
    transform: none;
    margin: 12px 0 16px;
  }
  .lnd-ex-card__go {
    opacity: 1;
    transform: none;
  }
}

