  align-items: center;
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--espiritu);
  transition: color 0.25s, letter-spacing 0.25s;
}
.lnd-news-card:hover .lnd-news-card__read {
  color: #fff;
  letter-spacing: 0.4px;
}

/* ── ARTÍCULOS ────────────────────────────────────────────── */
.lnd-articulos {
  position: relative;
  z-index: 10;
  padding: 80px clamp(18px, 5vw, 60px);
  /* Panel azul oscuro (en claro y oscuro) */
  background: linear-gradient(165deg, #21365a 0%, #0f1f38 100%);
}
.lnd-articulos__inner {
  max-width: var(--container-width);
  margin: 0 auto;
}
.lnd-articulos__header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  flex-wrap: wrap;
  border-bottom: 2px solid rgba(255, 255, 255, 0.14);
  padding-bottom: 22px;
  margin-bottom: 40px;
}
.lnd-articulos__tag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 0.72rem;
  letter-spacing: 2.5px;
  text-transform: uppercase;
  font-weight: 800;
  color: var(--espiritu);
}
.lnd-articulos__tag::before {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: 2px;
  background: var(--espiritu);
  flex-shrink: 0;
}
.lnd-articulos__title {
  font-weight: 900;
  font-size: clamp(2rem, 4.4vw, 3.2rem);
  letter-spacing: -0.035em;
  margin-top: 8px;
  color: #EAF4FF;
}
.lnd-articulos__intro {
  max-width: 34ch;
  color: rgba(234, 244, 255, 0.72);
  font-size: 0.96rem;
  line-height: 1.55;
  font-weight: 400;
}
.lnd-articulos__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: clamp(28px, 4vw, 56px);
  align-items: start;
}
@media (max-width: 880px) {
  .lnd-articulos__grid {
    grid-template-columns: 1fr;
  }
  .lnd-articulos__grid .lnd-art-preview {
    display: none !important;
  }
}
.lnd-articulos__cta {
  text-align: center;
  margin-top: 48px;
}

.lnd-art-preview {
  position: sticky;
  top: 90px;
  height: 660px;
}
.lnd-art-preview__panel {
  height: 100%;
  flex-direction: column;
  border-radius: 24px;
  overflow: hidden;
  /* Glassmorphism marcado: vidrio esmerilado sobre el panel azul oscuro */
  background: linear-gradient(155deg, rgba(255, 255, 255, 0.13), rgba(255, 255, 255, 0.04));
  border: 1px solid rgba(255, 255, 255, 0.2);
  backdrop-filter: blur(24px) saturate(1.4);
  -webkit-backdrop-filter: blur(24px) saturate(1.4);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.22), 0 34px 70px -40px rgba(0, 0, 0, 0.55);
  /* Ahora es un enlace al artículo activo */
  text-decoration: none;
  color: inherit;
  cursor: pointer;
  transition: transform 0.4s cubic-bezier(0.2, 0.8, 0.2, 1), box-shadow 0.4s ease;
}
.lnd-art-preview__panel:hover {
  transform: translateY(-4px);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.28), 0 44px 84px -40px rgba(0, 0, 0, 0.6), 0 0 34px -8px rgba(125, 198, 229, 0.5);
}
.lnd-art-preview__panel:focus-visible {
  outline: 2px solid var(--espiritu);
  outline-offset: 3px;
}
.lnd-art-preview__img-wrap {
  position: relative;
  height: 300px;
  flex: 0 0 300px;
  overflow: hidden;
}
.lnd-art-preview__img-wrap img:not(.lnd-art-preview__alex) {
  width: 100%;
  height: 100%;
  object-fit: cover;
  animation: lnd-kenburns 18s ease-in-out infinite alternate;
}
.lnd-art-preview__cat {
  position: absolute;
  top: 16px;
  left: 16px;
  padding: 6px 14px;
  border-radius: 100px;
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 1px;
  text-transform: uppercase;
  background: var(--bilbao);
  color: #fff;
}
.lnd-art-preview__body {
  padding: 28px 30px 26px;
  flex: 1;
  display: flex;
  flex-direction: column;
  position: relative;
}
.lnd-art-preview__alex {
  position: absolute;
  left: 14px;
  bottom: 14px;
  width: 80px;
  opacity: 0.85;
  filter: drop-shadow(0 4px 12px rgba(0, 0, 0, 0.3));
  pointer-events: none;
  z-index: 2;
}
.lnd-art-preview__title {
  font-weight: 900;
  font-size: clamp(1.5rem, 2.4vw, 1.95rem);
  line-height: 1.14;
  letter-spacing: -0.025em;
  margin-bottom: 12px;
  color: #EAF4FF;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.lnd-art-preview__excerpt {
  color: rgba(234, 244, 255, 0.75);
  line-height: 1.6;
  font-size: 0.98rem;
  margin-bottom: 20px;
  font-weight: 400;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.lnd-art-preview__foot {
  margin-top: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid rgba(255, 255, 255, 0.16);
  padding-top: 16px;
}
.lnd-art-preview__author {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.86rem;
  font-weight: 700;
  color: #fff;
}
.lnd-art-preview__author-dot {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--bilbao), var(--espiritu));
  flex: 0 0 auto;
}
.lnd-art-preview__time {
  font-size: 0.82rem;
  color: rgba(234, 244, 255, 0.55);
  font-weight: 600;
}

.lnd-art-list {
  display: flex;
  flex-direction: column;
}

.lnd-art-row {
  /* Van directamente sobre el panel azul oscuro → texto claro fijo */
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 20px;
  align-items: center;
  padding: 22px 14px;
  text-decoration: none;
  color: inherit;
  border-top: 1px solid rgba(255, 255, 255, 0.12);
  border-left: 2px solid transparent;
  border-radius: 0 12px 12px 0;
  transition: border-color 0.3s, background 0.3s, padding-left 0.3s;
}
.lnd-art-row:last-child {
  border-bottom: 1px solid rgba(255, 255, 255, 0.12);
}
.lnd-art-row__num {
  font-weight: 900;
  font-size: 1.5rem;
  line-height: 1;
  color: rgba(234, 244, 255, 0.34);
  letter-spacing: -0.03em;
}
.lnd-art-row__cat {
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 1.4px;
  text-transform: uppercase;
  color: var(--espiritu);
  display: block;
}
.lnd-art-row__title {
  font-weight: 700;
  font-size: 1.16rem;
  line-height: 1.28;
  letter-spacing: -0.015em;
  margin: 5px 0 4px;
  color: #EAF4FF;
}
.lnd-art-row__meta {
  font-size: 0.78rem;
  color: rgba(234, 244, 255, 0.5);
  font-weight: 500;
}
.lnd-art-row__arrow {
  font-size: 1.1rem;
  color: var(--espiritu);
  opacity: 0;
  transform: translateX(-6px);
  transition: all 0.3s;
}

/* ── VISITA / MAPA ────────────────────────────────────────── */
.lnd-visita {
  position: relative;
  z-index: 10;
  padding: 80px clamp(18px, 5vw, 60px);
  background: var(--bg);
}
.lnd-visita__grid {
  max-width: var(--container-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  gap: clamp(28px, 4vw, 56px);
  align-items: center;
}
@media (max-width: 880px) {
  .lnd-visita__grid {
    grid-template-columns: 1fr;
  }
}
.lnd-visita__eyebrow {
  font-size: 0.78rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--bilbao);
  display: block;
  margin-bottom: 10px;
}
.lnd-visita__title {
  font-weight: 900;
  font-size: clamp(2rem, 4.6vw, 3.4rem);
  letter-spacing: -0.035em;
  margin-bottom: 16px;
  color: var(--ink);
}
.lnd-visita__desc {
  color: var(--ink-soft);
  line-height: 1.62;
  font-size: 1.02rem;
  max-width: 46ch;
  margin-bottom: 28px;
  font-weight: 400;
}
.lnd-visita__info {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 30px;
}
.lnd-visita__info-row {
  display: flex;
  gap: 14px;
  align-items: flex-start;
}
@media (max-width: 880px) {
  .lnd-visita__eyebrow, .lnd-visita__title, .lnd-visita__desc {
    text-align: center;
  }
  .lnd-visita__desc {
    max-width: 100%;
    margin-inline: auto;
  }
  .lnd-visita {
    /* El bloque de datos se centra como conjunto, pero las filas
       mantienen su alineación a la izquierda para que las etiquetas
       (Dirección / Horario) queden alineadas entre sí */
  }
  .lnd-visita__info {
    width: max-content;
    max-width: 100%;
    margin-inline: auto;
  }
  .lnd-visita__info-row {
    justify-content: flex-start;
    text-align: left;
  }
  .lnd-visita__ctas {
    justify-content: center;
  }
}
@media (max-width: 480px) {
  .lnd-visita__ctas {
    flex-direction: column;
    align-items: stretch;
  }
  .lnd-visita__ctas > a {
    width: 100%;
    justify-content: center;
  }
}
.lnd-visita__info-icon {
  flex: 0 0 auto;
  width: 42px;
  height: 42px;
  border-radius: 12px;
  background: var(--glass);
  border: 1px solid var(--glass-brd);
  display: grid;
  place-items: center;
  color: var(--bilbao);
}
.lnd-visita__info-label {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 1.2px;
  font-weight: 800;
  color: var(--ink-faint);
  margin-bottom: 6px;
}
.lnd-visita__info-val {
  font-size: 0.94rem;
  color: var(--ink);
  line-height: 1.45;
  font-weight: 500;
}
.lnd-visita__hours {
  border-collapse: collapse;
  font-size: 0.84rem;
}
.lnd-visita__hours th {
  text-align: left;
  font-weight: 700;
  color: var(--ink);
  padding: 2px 20px 2px 0;
  white-space: nowrap;
}
.lnd-visita__hours td {
  font-variant-numeric: tabular-nums;
  color: var(--bilbao);
  font-weight: 600;
  text-align: right;
}
.lnd-visita__hours .is-closed {
  color: var(--ink-faint);
  font-style: italic;
  font-weight: 500;
}
.lnd-visita__hours tr + tr th, .lnd-visita__hours tr + tr td {
  border-top: 1px solid rgba(0, 0, 0, 0.05);
}
.lnd-visita__ctas {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}
.lnd-visita__map-link {
  display: block;
  text-decoration: none;
  border-radius: 26px;
  overflow: hidden;
  transition: transform 0.3s, box-shadow 0.3s;
}
.lnd-visita__map-link:hover {
  transform: translateY(-3px);
  box-shadow: 0 24px 60px rgba(20, 40, 70, 0.2);
}
.lnd-visita__map-wrap {
  position: relative;
  border-radius: 26px;
  overflow: hidden;
  border: 1px solid var(--glass-brd);
  box-shadow: 0 40px 90px -50px var(--glass-sh);
}
.lnd-visita__map-alex {
  position: absolute;
  right: 6px;
  bottom: 0;
  z-index: 4;
  width: clamp(86px, 14vw, 134px);
  filter: drop-shadow(0 14px 24px rgba(15, 40, 70, 0.4));
  animation: lnd-floaty2 7s ease-in-out infinite;
  scale: -1 1;
}
.lnd-visita__map-pin {
  position: absolute;
  left: 64%;
  top: 53%;
  transform: translate(-50%, -50%);
  z-index: 3;
  display: flex;
  flex-direction: column;
  align-items: center;
}
.lnd-visita__pin-dot {
  position: relative;
  width: 22px;
  height: 22px;
}
.lnd-visita__pin-dot::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: var(--bilbao);
  animation: lnd-ping 1.9s ease-out infinite;
}
.lnd-visita__pin-dot::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: var(--bilbao);
  border: 3px solid #fff;
  box-shadow: 0 4px 12px rgba(20, 40, 70, 0.4);
}
.lnd-visita__pin-label {
  margin-top: 9px;
  padding: 6px 13px;
  border-radius: 10px;
  background: #fff;
  color: #16202E;
  font-size: 0.8rem;
  font-weight: 800;
  box-shadow: 0 8px 22px rgba(20, 40, 70, 0.28);
  white-space: nowrap;
}

/* ── CTA FINAL ────────────────────────────────────────────── */
.lnd-cta {
  position: relative;
  z-index: 10;
  padding: clamp(80px, 12vw, 150px) clamp(18px, 5vw, 60px) 70px;
  text-align: center;
  overflow: hidden;
  background: radial-gradient(125% 100% at 50% 18%, var(--bg2) 0%, var(--bg) 72%);
}
.lnd-cta__alex-left {
  position: absolute;
  left: clamp(-30px, 3vw, 60px);
  bottom: 90px;
  width: clamp(120px, 15vw, 210px);
  filter: drop-shadow(0 18px 32px rgba(15, 40, 70, 0.3));
  animation: lnd-floaty 6.5s ease-in-out infinite;
  z-index: 1;
}
.lnd-cta__alex-right {
  position: absolute;
  right: clamp(-30px, 3vw, 60px);
  bottom: 100px;
  width: clamp(120px, 15vw, 210px);
  filter: drop-shadow(0 18px 32px rgba(15, 40, 70, 0.3));
  animation: lnd-floaty2 7.5s ease-in-out infinite;
  z-index: 1;
}
.lnd-cta__content {
  position: relative;
  z-index: 2;
  max-width: 780px;
  margin: 0 auto;
}
.lnd-cta__eyebrow {
  display: inline-block;
  font-size: 0.8rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--bilbao);
  margin-bottom: 18px;
}
.lnd-cta__title {
  font-weight: 900;
  font-size: clamp(2.4rem, 6.6vw, 5.2rem);
  line-height: 1;
  letter-spacing: -0.04em;
  margin-bottom: 32px;
  color: var(--ink);
}
.lnd-cta__title span {
  background: linear-gradient(110deg, var(--bilbao), var(--espiritu));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
@media (max-width: 767px) {
  .lnd-cta__title {
    margin-bottom: 24px;
  }
}
.lnd-cta {
  /* ── Móvil: las mascotas dejan de encimarse con el título/botón ──
     Se reducen y se anclan a las esquinas inferiores, dentro de una
     banda de padding reservada debajo del contenido */
}
@media (max-width: 767px) {
  .lnd-cta {
    padding-top: clamp(56px, 12vw, 80px);
    padding-bottom: 150px;
  }
  .lnd-cta__content {
    padding-bottom: 8px;
  }
  .lnd-cta__alex-left, .lnd-cta__alex-right {
    width: clamp(86px, 26vw, 118px);
    bottom: 14px;
    animation-duration: 7s;
  }
  .lnd-cta__alex-left {
    left: -8px;
  }
  .lnd-cta__alex-right {
    right: -8px;
  }
}
@media (max-width: 360px) {
  .lnd-cta__alex-left, .lnd-cta__alex-right {
    display: none;
  }
}

/* ── STICKY CTA (solo móvil) — píldora sutil y centrada ───── */
.lnd-sticky-cta {
  display: none;
  position: fixed;
  left: 0;
  right: 0;
  bottom: calc(14px + env(safe-area-inset-bottom, 0px));
  z-index: 70;
  text-align: center;
  transform: translateY(160%);
  opacity: 0;
  transition: transform 0.45s cubic-bezier(0.2, 0.8, 0.2, 1), opacity 0.35s ease;
  pointer-events: none;
}
.lnd-sticky-cta.is-visible {
  transform: none;
  opacity: 1;
}
.lnd-sticky-cta__btn {
  pointer-events: auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 22px;
  border-radius: 100px;
  background: var(--glass);
  border: 1px solid var(--glass-brd);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  color: var(--col-bilbao);
  font-weight: 700;
  font-size: 0.92rem;
  letter-spacing: 0.2px;
  text-decoration: none;
  box-shadow: 0 8px 26px -10px var(--glass-sh);
  transition: background 0.25s ease;
}
.lnd-sticky-cta__btn:active {
  background: var(--card);
}
.lnd-sticky-cta__btn svg {
  flex: 0 0 auto;
  opacity: 0.9;
}
@media (max-width: 767px) {
  .lnd-sticky-cta {
    display: block;
  }
}

/* =========================================================
   LANDING · SOMOS COMUNIDAD  (banda contrastante, layout dividido)
========================================================= */
.lnd-comunidad {
  position: relative;
  z-index: 10;
  max-width: var(--container-width);
  width: calc(100% - 2 * clamp(18px, 5vw, 60px));
  margin: clamp(24px, 5vw, 56px) auto 60px;
  border-radius: 28px;
  /* Glassmorphism sobre el fondo Three.js */
  background: radial-gradient(120% 140% at 90% 8%, rgba(77, 138, 187, 0.35), transparent 48%), radial-gradient(110% 120% at 4% 98%, rgba(66, 103, 172, 0.3), transparent 50%), rgba(9, 25, 51, 0.55);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border: 1px solid rgba(255, 255, 255, 0.14);
  box-shadow: 0 40px 80px -40px rgba(8, 26, 54, 0.7), inset 0 1px 0 rgba(255, 255, 255, 0.12);
  overflow: hidden;
}

.lnd-comunidad__inner {
  max-width: 1160px;
  margin: 0 auto;
  padding: clamp(44px, 6vw, 68px) clamp(28px, 4vw, 52px);
  display: grid;
  grid-template-columns: 0.92fr 1.08fr;
  gap: 48px;
  align-items: center;
}

.lnd-comunidad__intro {
  position: relative;
  color: #fff;
}

.lnd-comunidad__eyebrow {
  display: inline-block;
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 1.6px;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.65);
  margin-bottom: 14px;
}

.lnd-comunidad__title {
  font-size: clamp(2rem, 3.8vw, 2.9rem);
  font-weight: 900;
  color: #fff;
  letter-spacing: -0.5px;
  line-height: 1.08;
  margin-bottom: 14px;
}

.lnd-comunidad__desc {
  font-size: 1.05rem;
  line-height: 1.6;
  color: rgba(255, 255, 255, 0.82);
  max-width: 340px;
  margin-bottom: 8px;
}

.lnd-comunidad__mascot {
  width: 150px;
  height: auto;
  margin-top: 8px;
  filter: drop-shadow(0 16px 26px rgba(0, 0, 0, 0.45));
  animation: lnd-com-float 3.6s ease-in-out infinite;
}

@keyframes lnd-com-float {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-9px);
  }
}
.lnd-comunidad__list {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.lnd-com-row {
  position: relative;
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 20px 22px;
  border-radius: 18px;
  background: #fff;
  text-decoration: none;
  box-shadow: 0 12px 30px -18px rgba(0, 0, 0, 0.5);
  transition: transform 0.24s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.24s;
  overflow: hidden;
}
.lnd-com-row::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 5px;
}
.lnd-com-row:hover {
  transform: translateX(8px);
  box-shadow: 0 20px 44px -18px rgba(0, 0, 0, 0.6);
}

.lnd-com-row__icon {
  flex-shrink: 0;
  width: 54px;
  height: 54px;
  border-radius: 15px;
  display: grid;
  place-items: center;
  font-size: 21px;
  color: #fff;
}

.lnd-com-row__text {
  flex: 1;
  min-width: 0;
}

.lnd-com-row__title {
  display: block;
  font-size: 1.2rem;
  font-weight: 800;
  color: var(--col-bilbao);
}

.lnd-com-row__desc {
  display: block;
  font-size: 0.9rem;
  line-height: 1.45;
  color: var(--col-herencia);
  opacity: 0.8;
  margin-top: 2px;
}

.lnd-com-row__arrow {
  flex-shrink: 0;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: #eef3fb;
  color: var(--col-bilbao);
  display: grid;
  place-items: center;
  transition: background 0.2s ease, transform 0.2s ease, color 0.2s ease;
