/* =========================================================
   VIEW TRANSITIONS — blog section
========================================================= */
@view-transition {
  navigation: auto;
}
/* Fade suave para el fondo de página (todo excepto los elementos con nombre propio) */
::view-transition-old(root),
::view-transition-new(root) {
  animation-duration: 0.32s;
  animation-timing-function: ease-out;
}

::view-transition-old(root) {
  animation-name: vt-fade-out;
}

::view-transition-new(root) {
  animation-name: vt-fade-in;
}

@keyframes vt-fade-out {
  to {
    opacity: 0;
  }
}
@keyframes vt-fade-in {
  from {
    opacity: 0;
  }
}
/* Elementos con nombre propio (card → hero): duración más larga, easing enérgico */
::view-transition-group(*) {
  animation-duration: 0.5s;
  animation-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
}

/* Los snapshots del elemento compartido se comportan como imágenes que rellenan su caja */
::view-transition-old(*),
::view-transition-new(*) {
  object-fit: cover;
  overflow: clip;
}

/* =========================================================
   BLOG HOME — listado de artículos
========================================================= */
.blog-home {
  padding-top: var(--header-height);
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
  min-height: 100vh;
}

/* ── SUBNAV ─────────────────────────────────────────────── */
.blog-subnav {
  background: #fff;
  border-bottom: 1.5px solid rgba(77, 138, 187, 0.12);
  position: sticky;
  top: var(--header-height);
  z-index: 80;
  box-shadow: 0 2px 14px rgba(15, 23, 42, 0.05);
}
.blog-subnav .container {
  display: flex;
  align-items: center;
  padding: 0 24px;
  height: 50px;
  gap: 0;
}

.blog-subnav-brand {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--col-herencia);
  flex-shrink: 0;
  padding-right: 20px;
  border-right: 1px solid var(--col-borde);
  text-decoration: none;
  transition: color 0.2s;
}
.blog-subnav-brand svg {
  color: var(--col-bilbao);
  flex-shrink: 0;
}
.blog-subnav-brand:hover {
  color: var(--col-bilbao);
}

.blog-subnav-links {
  display: flex;
  gap: 2px;
  padding: 0 14px;
  flex: 1;
  overflow-x: auto;
  scrollbar-width: none;
}
.blog-subnav-links::-webkit-scrollbar {
  display: none;
}

.blog-subnav-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  border-radius: 999px;
  font-size: 0.79rem;
  font-weight: 600;
  color: var(--col-texto);
  opacity: 0.55;
  text-decoration: none;
  white-space: nowrap;
  transition: all 0.2s;
}
.blog-subnav-link:hover {
  background: rgba(77, 138, 187, 0.09);
  color: var(--col-bilbao);
  opacity: 1;
}
.blog-subnav-link.active {
  background: rgba(77, 138, 187, 0.1);
  color: var(--col-bilbao);
  opacity: 1;
  font-weight: 700;
}

.blog-subnav-end {
  flex-shrink: 0;
  padding-left: 16px;
  border-left: 1px solid var(--col-borde);
  display: flex;
  align-items: center;
  gap: 10px;
}

.blog-subnav-count {
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--col-texto);
  opacity: 0.34;
  white-space: nowrap;
}

/* ── HERO ───────────────────────────────────────────────── */
.blog-home-hero {
  position: relative;
  padding: 48px 0 0; /* estandarizado con /noticias */
  overflow: hidden;
  background: #fff;
  /* Large blue radial glow top-right */
}
.blog-home-hero::before {
  content: "";
  position: absolute;
  top: -30%;
  right: -10%;
  width: 65%;
  height: 160%;
  background: radial-gradient(ellipse 70% 70% at 60% 40%, rgba(66, 103, 172, 0.09) 0%, rgba(70, 189, 198, 0.05) 50%, transparent 75%);
  pointer-events: none;
}
.blog-home-hero {
  /* Thin blue left accent bar */
}
.blog-home-hero::after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 4px;
  height: 100%;
  background: linear-gradient(to bottom, var(--col-bilbao), #46bdc6);
  z-index: 1;
}
.blog-home-hero .container {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: flex-end; /* estandarizado con /noticias */
  gap: 40px;
  /* Sin override de padding: usa el gutter del .container global,
     idéntico al de .blog-featured / .blog-posts → alineados. */
}

.blog-home-hero-body {
  flex: 1 1 0;
  min-width: 0;
  padding-bottom: 52px; /* estandarizado con /noticias */
}

.blog-hero-mascot {
  flex: 0 0 auto;
  width: clamp(200px, 26vw, 400px); /* más grande: aprovecha el espacio (imagen vertical) */
  display: none;
  align-self: flex-end;
  pointer-events: none;
  filter: drop-shadow(0 20px 40px rgba(0, 0, 0, 0.42));
}
@media (min-width: 640px) {
  .blog-hero-mascot {
    display: block;
  }
}

.blog-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 8px 16px 8px 6px;
  border-radius: 999px;
  background: rgba(66, 103, 172, 0.07);
  color: var(--col-herencia);
  font-weight: 700;
  font-size: 0.85rem;
  margin-bottom: 18px;
  border: 1px solid rgba(66, 103, 172, 0.16);
}

.blog-eyebrow-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--col-bilbao);
  color: #fff;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 999px;
}

.blog-home-title {
  max-width: 920px;
  font-size: clamp(2.4rem, 6vw, 5.2rem);
  line-height: 0.95;
  letter-spacing: -0.04em;
  color: var(--col-herencia);
  margin-bottom: 20px;
}
.blog-home-title em {
  font-style: normal;
  color: var(--col-bilbao);
}

.blog-home-lead {
  max-width: 580px;
  font-size: 0.95rem;
  font-weight: 400;
  line-height: 1.8;
  color: var(--col-texto);
  opacity: 0.82;
  margin-bottom: 28px;
}

.blog-home-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
}
.blog-home-actions .btn-primario {
  font-size: 0.875rem;
  padding: 12px 26px;
  background: var(--col-bilbao);
  color: #fff;
  border-color: var(--col-bilbao);
}
.blog-home-actions .btn-primario:hover {
  background: var(--col-herencia);
  border-color: var(--col-herencia);
}
.blog-home-actions .btn-secundario {
  font-size: 0.875rem;
  padding: 12px 26px;
  background: transparent;
  color: var(--col-herencia);
  border-color: rgba(66, 103, 172, 0.3);
}
.blog-home-actions .btn-secundario:hover {
  background: rgba(66, 103, 172, 0.07);
  border-color: var(--col-bilbao);
  color: var(--col-bilbao);
}

/* ── TOPICS STRIP (marquee de artículos) ────────────────── */
.blog-topics-strip {
  position: relative;
  z-index: 2;
  width: 100%;
  background: var(--col-herencia);
  overflow: hidden;
}

.blog-topics-inner {
  display: flex;
  align-items: stretch;
}

.blog-topics-label {
  flex-shrink: 0;
  background: rgba(255, 255, 255, 0.08);
  color: rgba(255, 255, 255, 0.65);
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  padding: 12px 20px;
  display: flex;
  align-items: center;
  gap: 8px;
  white-space: nowrap;
  border-right: 1px solid rgba(255, 255, 255, 0.08);
}
.blog-topics-label svg {
  opacity: 0.55;
  flex-shrink: 0;
}

.blog-topics-track-wrap {
  overflow: hidden;
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
}

.blog-topics-track {
  display: flex;
  align-items: center;
  gap: 10px;
  animation: ticker-scroll 90s linear infinite;
  will-change: transform;
  white-space: nowrap;
  padding: 10px 10px;
}
.blog-topics-track:hover {
  animation-play-state: paused;
}

.blog-topic-pill {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 6px 16px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.09);
  color: rgba(255, 255, 255, 0.8);
  font-size: 0.77rem;
  font-weight: 600;
  border: 1px solid rgba(255, 255, 255, 0.11);
  flex-shrink: 0;
  text-decoration: none;
  cursor: default;
  transition: background 0.22s, color 0.22s;
}
.blog-topic-pill:hover {
  background: rgba(255, 255, 255, 0.18);
  color: #fff;
}

.topic-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
  opacity: 0.85;
}

/* ARTÍCULO DESTACADO */
.blog-featured {
  /* Sin padding horizontal: el .container interno ya aporta el gutter,
     así queda alineado con el hero (que solo usa .container). */
  padding: 24px 0 36px;
}

.blog-section-head {
  display: flex;
  justify-content: space-between;
  align-items: end;
  gap: 20px;
  margin-bottom: 28px;
}

.blog-section-title {
  font-size: clamp(1.8rem, 4vw, 2.8rem);
  color: var(--col-herencia);
  letter-spacing: -0.03em;
}

.blog-section-copy {
  max-width: 540px;
  font-size: 0.9rem;
  font-weight: 300;
  color: var(--col-texto);
  opacity: 0.85;
}

.featured-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}
@media (min-width: 1024px) {
  .featured-grid {
    grid-template-columns: 1.25fr 0.75fr;
    align-items: stretch;
  }
}

.featured-main-card {
  position: relative;
  min-height: 540px;
  border-radius: 32px;
  overflow: hidden;
  box-shadow: 0 30px 60px rgba(15, 23, 42, 0.12);
  background: #dbeafe;
}
.featured-main-card img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.featured-main-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: end;
  background: linear-gradient(180deg, rgba(0, 0, 0, 0.08) 0%, rgba(15, 23, 42, 0.82) 100%);
  padding: 32px;
}

.featured-main-content {
  color: #fff;
  max-width: 700px;
}

.post-kicker {
  display: inline-block;
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  padding: 9px 14px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.16);
  backdrop-filter: blur(10px);
  margin-bottom: 16px;
}

.featured-main-title {
  font-size: clamp(2rem, 4vw, 3.2rem);
  line-height: 1;
  letter-spacing: -0.035em;
  margin-bottom: 14px;
}

.featured-main-excerpt {
  font-size: 0.9rem;
  font-weight: 300;
  line-height: 1.75;
  opacity: 0.94;
  margin-bottom: 18px;
}

.post-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: center;
  font-size: 0.95rem;
  opacity: 0.88;
}

.featured-side {
  display: grid;
  gap: 20px;
}

/* TARJETAS DE POST */
.mini-post-card {
  background: #fff;
  border: 1px solid var(--col-borde);
  border-radius: 24px;
  overflow: hidden;
  box-shadow: 0 12px 24px rgba(15, 23, 42, 0.04);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}
.mini-post-card img {
  width: 100%;
  height: 200px;
  display: block;
  object-fit: cover;
}

.mini-post-card:hover,
.post-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 18px 40px rgba(15, 23, 42, 0.08);
}

.post-card img {
  width: 100%;
  height: 240px;
  display: block;
  object-fit: cover;
}

.mini-post-body,
.post-card-body {
  padding: 22px;
}

.mini-post-title {
  font-size: 1.25rem;
  line-height: 1.15;
  color: var(--col-herencia);
  margin: 10px 0;
}

.mini-post-excerpt,
.post-card-excerpt {
  font-size: 0.88rem;
  font-weight: 300;
  color: var(--col-texto);
  opacity: 0.85;
  line-height: 1.7;
}

/* GRID DE POSTS */
.blog-posts {
  /* Igual que .blog-featured: alineado al gutter del .container */
  padding: 24px 0 80px;
}

/* Móvil: menos margen horizontal para aprovechar el ancho */
@media (max-width: 600px) {
  .blog-home-hero .container,
  .blog-featured .container,
  .blog-posts .container {
    padding-left: 14px;
    padding-right: 14px;
  }
}
.posts-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}
@media (min-width: 768px) {
  .posts-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}
@media (min-width: 1200px) {
  .posts-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.post-card {
  background: #fff;
  border: 1px solid var(--col-borde);
  border-radius: 26px;
  overflow: hidden;
  transition: transform 0.3s ease, box-shadow 0.3s ease, opacity 0.2s ease;
}

.post-card-title {
  font-size: 1.45rem;
  line-height: 1.1;
  color: var(--col-herencia);
  margin: 12px 0 10px;
  letter-spacing: -0.02em;
}

.post-card-categories {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 14px;
}
.post-card-categories .article-category {
  cursor: pointer;
}

.post-author {
  display: flex;
  align-items: center;
  gap: 8px;
}

.post-author-avatar {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  overflow: hidden;
  background: var(--col-bilbao);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.post-author-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.post-author-avatar span {
  color: #fff;
  font-size: 0.6rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  line-height: 1;
}

.post-card.is-hidden {
  display: none;
}

.read-more {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 18px;
  font-size: 0.875rem;
  font-weight: 700;
  color: var(--col-bilbao);
}
.read-more:hover {
  color: var(--col-herencia);
}

/* BÚSQUEDA */
.blog-search-wrap {
  margin-bottom: 24px;
}

.blog-search-input-wrap {
  position: relative;
  max-width: 580px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.6);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border: 1.5px solid rgba(255, 255, 255, 0.75);
  box-shadow: 0 4px 20px rgba(77, 138, 187, 0.09), 0 1px 4px rgba(15, 23, 42, 0.06);
  transition: max-width 0.3s ease, box-shadow 0.25s ease, border-color 0.25s ease;
}
.blog-search-input-wrap:focus-within {
  max-width: 640px;
  border-color: rgba(77, 138, 187, 0.45);
  box-shadow: 0 0 0 4px rgba(77, 138, 187, 0.1), 0 4px 24px rgba(77, 138, 187, 0.12);
}
.blog-search-input-wrap svg {
  position: absolute;
  left: 16px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--col-herencia);
  opacity: 0.75;
  pointer-events: none;
  z-index: 2;
  transition: opacity 0.2s;
}
.blog-search-input-wrap:focus-within svg {
  opacity: 1;
  color: var(--col-bilbao);
}

.blog-search-input {
  width: 100%;
  padding: 13px 44px 13px 44px;
  border: none;
  border-radius: 999px;
  font-size: 0.9rem;
  font-family: inherit;
  background: transparent;
  color: var(--col-texto);
  outline: none;
  appearance: none;
  -webkit-appearance: none;
}
.blog-search-input::placeholder {
  color: var(--col-texto);
  opacity: 0.38;
}
.blog-search-input::-webkit-search-cancel-button {
  -webkit-appearance: none;
  appearance: none;
}

.blog-search-clear {
  position: absolute;
  right: 14px;
  top: 50%;
  transform: translateY(-50%);
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: rgba(77, 138, 187, 0.12);
  border: none;
  cursor: pointer;
  display: none;
  align-items: center;
  justify-content: center;
  color: var(--col-bilbao);
  font-size: 0.7rem;
  padding: 0;
  z-index: 2;
  transition: background 0.18s, transform 0.18s;
}
.blog-search-clear:hover {
  background: rgba(77, 138, 187, 0.24);
  transform: translateY(-50%) scale(1.1);
}
.blog-search-clear.visible {
  display: flex;
}

/* PAGINACIÓN */
.blog-pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  margin-top: 40px;
  flex-wrap: wrap;
}

.blog-page-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 38px;
  height: 38px;
  padding: 0 12px;
  border-radius: 10px;
  border: 1.5px solid rgba(77, 138, 187, 0.18);
  background: #fff;
  color: var(--col-texto);
  font-size: 0.85rem;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: all 0.18s ease;
  white-space: nowrap;
}
.blog-page-btn:hover {
  border-color: var(--col-bilbao);
  color: var(--col-bilbao);
  background: rgba(77, 138, 187, 0.06);
}
.blog-page-btn.active {
  background: var(--col-bilbao);
  border-color: var(--col-bilbao);
  color: #fff;
  box-shadow: 0 4px 12px rgba(77, 138, 187, 0.3);
}
.blog-page-btn:disabled {
  opacity: 0.38;
  cursor: not-allowed;
}

.blog-page-info {
  font-size: 0.78rem;
  color: var(--text-gray);
  margin-right: 6px;
  white-space: nowrap;
}

/* FILTROS */
.category-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 32px;
}

/* ESTADO VACÍO */
.empty-state {
  display: none;
  padding: 40px 24px;
  border-radius: 24px;
  background: #fff;
  border: 1px solid var(--col-borde);
  text-align: center;
  color: var(--col-texto);
}
.empty-state.show {
  display: block;
}

/* CTA BLOG */
.blog-cta {
  padding: 0 24px 110px;
}

.blog-cta-box {
  background: linear-gradient(135deg, var(--col-herencia) 0%, #1a4a9f 50%, var(--col-bilbao) 100%);
  color: #fff;
  border-radius: 28px;
  padding: 52px 32px;
  text-align: center;
  box-shadow: 0 28px 60px rgba(15, 23, 42, 0.2);
  position: relative;
  overflow: hidden;
}
.blog-cta-box::before {
  content: "";
  position: absolute;
  top: -40%;
  right: -8%;
  width: 55%;
  height: 200%;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.05), transparent 68%);
  pointer-events: none;
}
.blog-cta-box h3 {
  font-size: clamp(1.8rem, 4vw, 2.4rem);
  margin-bottom: 14px;
  letter-spacing: -0.03em;
}
.blog-cta-box p {
  max-width: 620px;
  margin: 0 auto 28px;
  font-size: 0.95rem;
  font-weight: 300;
  line-height: 1.75;
  opacity: 0.9;
}
.blog-cta-box .btn-terciario {
  font-size: 0.875rem;
  padding: 12px 30px;
}

/* =========================================================
   PÁGINA EN CONSTRUCCIÓN
========================================================= */
.admisiones-title {
  color: var(--col-bilbao);
  font-size: 64px;
  font-weight: 900;
}

.main-construction {
  flex-grow: 1;
  padding-top: var(--header-height);
  display: flex;
  align-items: center;
  justify-content: center;
  padding-bottom: 64px;
  min-height: 60vh;
}

.construction-container {
  text-align: center;
  max-width: 800px;
  padding: 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.construction-image {
  max-width: 100%;
  height: auto;
  max-height: 400px;
  border-radius: 16px;
  box-shadow: 0 12px 24px rgba(77, 138, 187, 0.15);
  margin-bottom: 32px;
  object-fit: cover;
}

.construction-title {
  font-size: 2.5rem;
  color: var(--col-bilbao);
  margin-bottom: 24px;
  letter-spacing: -1px;
}

.construction-lead,
p.lead {
  font-size: 1.1rem;
  color: var(--col-herencia);
  margin-bottom: 32px;
  line-height: 1.6;
}

/* =========================================================
   ADMISIONES — página de inicio
========================================================= */
.hero-section {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  background-color: #fff;
  overflow: hidden;
  padding-top: 40px;
}

.hero-blob-bg {
  position: absolute;
  right: -15%;
  top: -20%;
  width: 70vw;
  height: 70vw;
  background: radial-gradient(circle, rgba(77, 138, 187, 0.08) 0%, rgba(255, 255, 255, 0) 70%);
  border-radius: 50%;
  z-index: 0;
  pointer-events: none;
  animation: pulseBlob 10s infinite alternate;
}

@keyframes pulseBlob {
  0% {
    transform: scale(1);
  }
  100% {
    transform: scale(1.1);
  }
}
.hero-grid {
  display: grid;
  grid-template-columns: 1fr;
