}

.admin-sidebar__alex {
  padding: 20px 20px 24px;
  border-top: 1px solid rgba(255, 255, 255, 0.07);
  text-align: center;
}
.admin-sidebar__alex img {
  width: 110px;
  margin: 0 auto;
