  opacity: 1;
}

.alex-modal__img {
  width: 130px;
  max-height: 190px;
  object-fit: contain;
  flex-shrink: 0;
  align-self: center;
}

.alex-modal__body {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 10px;
  flex: 1;
  min-width: 0;
}

.alex-modal__tipo {
  font-size: 1.15rem;
  font-weight: 800;
  color: #0F172A;
  margin: 0;
}

.alex-modal__msg {
  font-size: 0.9rem;
  color: #374C69;
  line-height: 1.6;
  margin: 0;
}

.alex-modal__actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  margin-top: 4px;
}

.alex-modal__cta {
  font-size: 0.82rem !important;
}

@media (max-width: 520px) {
  .alex-modal__card {
    flex-direction: column;
    align-items: center;
    text-align: center;
    padding: 20px;
  }
  .alex-modal__img {
    width: 100px;
    align-self: center;
  }
  .alex-modal__actions {
    justify-content: center;
  }
}
/* =========================================================
   PERFIL Y PERMISOS (crear/editar usuario)

   Dos bloques con nombres homónimos —el módulo «Profesores» (un directorio que se
   consulta) y el tipo «Profesor» (lo que alguien ES)— compartían la misma tarjeta y
   eran indistinguibles. Ahora cada pregunta tiene su propio lenguaje visual:

     .admin-tipo-card  identidad → tarjeta alta, icono relleno del color del tipo
     .admin-mod-chip   permiso   → chip bajo, casilla cuadrada a la vista

   Los dos van precedidos de su .admin-form-step numerado.
========================================================= */
/* ── Encabezado de paso ── */
.admin-form-step {
  display: flex;
  align-items: flex-start;
  gap: 13px;
  margin-bottom: 18px;
}
.admin-form-step--sep {
  margin-top: 34px;
  padding-top: 26px;
  border-top: 1px dashed #e2e8f0;
}
.admin-form-step__n {
  width: 30px;
  height: 30px;
  flex-shrink: 0;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 0.85rem;
  font-weight: 800;
  color: #fff;
  background: linear-gradient(135deg, #2e4b8a, #4267ac);
  box-shadow: 0 5px 14px -6px rgba(66, 103, 172, 0.7);
}
.admin-form-step__txt {
  min-width: 0;
  padding-top: 1px;
  /* ⚠️ HIJO DIRECTO, no descendiente. Con `strong` a secas la regla alcanzaba
     también al énfasis escrito DENTRO del `<small>`, y cada palabra resaltada
     se partía a su propia línea: «Sus permisos. El / Administrador / accede a
     todo…» se leía como tres frases rotas en vez de una. */
}
.admin-form-step__txt > strong {
  display: block;
  font-size: 0.98rem;
  font-weight: 800;
  color: #0B1F3D;
}
.admin-form-step__txt > small {
  display: block;
  margin-top: 3px;
  font-size: 0.82rem;
  color: var(--text-gray, #64748B);
  line-height: 1.55;
}

/* Ayuda que va ANTES del campo (explica la regla antes de elegir), no después */
.admin-form__hint--pre {
  display: block;
  margin: -6px 0 14px;
  font-size: 0.8rem;
  line-height: 1.55;
}

/* Campo que depende de otro (niveles, que solo aplica a Profesor) */
.admin-subcampo {
  margin-top: 22px;
  padding-left: 16px;
  border-left: 3px solid #e8eef7;
}
.admin-subcampo[hidden] {
  display: none;
}

/* ── Tipo de personal: tarjetas de identidad ── */
.admin-tipo-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(212px, 1fr));
  gap: 12px;
}

.admin-tipo-card {
  display: flex;
  cursor: pointer;
}
.admin-tipo-card input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}
.admin-tipo-card__box {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  flex: 1;
  padding: 18px 16px 16px;
  border: 1.5px solid #e2e8f0;
  border-radius: 16px;
  background: #fff;
  transition: border-color 0.18s ease, background 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
}
.admin-tipo-card:hover .admin-tipo-card__box {
  border-color: var(--c, #c7d6ea);
  transform: translateY(-2px);
}
.admin-tipo-card__icon {
  width: 44px;
  height: 44px;
  border-radius: 13px;
  display: grid;
  place-items: center;
  font-size: 17px;
  margin-bottom: 12px;
  /* El icono nace ya teñido del color del tipo: es lo que hace que la tarjeta
     se lea como una identidad y no como una casilla más. */
  color: #fff;
  background: var(--c, #4267ac);
  box-shadow: 0 8px 18px -9px color-mix(in srgb, var(--c, #4267ac) 85%, transparent);
}
.admin-tipo-card__name {
  font-size: 15px;
  font-weight: 800;
  color: #0B1F3D;
  margin-bottom: 4px;
}
.admin-tipo-card__desc {
  font-size: 12px;
  color: #64748B;
  line-height: 1.5;
}
.admin-tipo-card__tag {
  margin-top: 10px;
  font-size: 9.5px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--c, #4267ac);
  background: color-mix(in srgb, var(--c, #4267ac) 12%, #fff);
  border-radius: 999px;
  padding: 3px 9px;
}
.admin-tipo-card {
  /* Marcada: el color del tipo toma el borde y el fondo */
}
input:checked + .admin-tipo-card__box {
  border-color: var(--c, #4267ac);
  background: color-mix(in srgb, var(--c, #4267ac) 7%, #fff);
  box-shadow: 0 10px 26px -14px color-mix(in srgb, var(--c, #4267ac) 90%, transparent);
}
.admin-tipo-card {
  /* Marca de verificación en la esquina, para que "elegido" no dependa solo del color */
}
input:checked + .admin-tipo-card__box::after {
  content: "\f00c";
  font-family: "Font Awesome 6 Free";
  font-weight: 900;
  position: absolute;
  top: 12px;
  right: 12px;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 9px;
  color: #fff;
  background: var(--c, #4267ac);
}
input:focus-visible + .admin-tipo-card__box {
  outline: 2px solid var(--c, #4267ac);
  outline-offset: 2px;
}
.admin-tipo-card {
  /* Bloqueada por exclusividad (prefecto/directivo no se combinan). Lo aplica
     admin-usuario-permisos.js. */
}
.admin-tipo-card.is-disabled {
  cursor: not-allowed;
}
.admin-tipo-card.is-disabled .admin-tipo-card__box {
  opacity: 0.42;
  background: #F8FAFC;
  transform: none;
}
.admin-tipo-card.is-disabled:hover .admin-tipo-card__box {
  border-color: #E2E8F0;
  transform: none;
}

/* ── Módulos: chips de permiso ──
   Deliberadamente bajos y con casilla cuadrada visible: a un chip no se le puede
   confundir con una tarjeta de identidad ni de lejos.

   Solo el NOMBRE del módulo. La descripción se leía una vez y luego eran trece líneas
   de texto entre el admin y las casillas que venía a marcar; sigue en el `title`.
   ⚠️ `.admin-tipo-card` (el hermano visual, más arriba) SÍ conserva su `__desc` a
   propósito: ahí la pregunta es "qué es esta persona" y sin la descripción «Profesor»
   vs «Directivo» se vuelve ambiguo. */
.admin-mod-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 10px;
}

.admin-mod-chip {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 12px 14px;
  border: 1.5px solid #e8edf4;
  border-radius: 12px;
  background: #fbfcfe;
  cursor: pointer;
  transition: border-color 0.16s ease, background 0.16s ease;
}
.admin-mod-chip input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}
.admin-mod-chip:hover {
  border-color: #c7d6ea;
  background: #fff;
}
.admin-mod-chip__box {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  border: 1.5px solid #cbd5e1;
  border-radius: 6px;
  background: #fff;
  display: grid;
  place-items: center;
  font-size: 10px;
  color: #fff;
  transition: background 0.16s ease, border-color 0.16s ease;
}
.admin-mod-chip__box i {
  opacity: 0;
  transition: opacity 0.12s ease;
}
.admin-mod-chip__icon {
  width: 26px;
  flex-shrink: 0;
  text-align: center;
  font-size: 15px;
  color: #94A3B8;
  transition: color 0.16s ease;
}
.admin-mod-chip {
  /* Sin `ellipsis`: el recorte lo pedía «Directorio · Administrativos», y los cuatro
     directorios dejaron de ser asignables (son transversales). Con las etiquetas que
     quedan —la más larga es «Suplencias»— sobra ancho de columna, y un nombre de
     módulo cortado es justo el dato que hay que leer para marcar la casilla. */
}
.admin-mod-chip__name {
  flex: 1 1 auto;
  min-width: 0;
  font-size: 14px;
  font-weight: 700;
  color: #1E293B;
  line-height: 1.35;
}
input:checked ~ .admin-mod-chip__icon {
  color: #4267ac;
}
input:checked + .admin-mod-chip__box {
  background: #4267ac;
  border-color: #4267ac;
}
input:checked + .admin-mod-chip__box i {
  opacity: 1;
}
.admin-mod-chip:has(input:checked) {
  border-color: #a8c2e6;
  background: #f5f9ff;
}
input:focus-visible + .admin-mod-chip__box {
  outline: 2px solid #4267ac;
  outline-offset: 2px;
}

.admin-modulos {
  border-top: 1px dashed #e2e8f0;
  padding-top: 20px;
}

/* Aviso de «se marcaron los módulos recomendados». Va en verde y no en azul de aviso:
   no es una advertencia, es la confirmación de una ayuda que acaba de ocurrir.
   ⚠️ `display:flex` obliga a su propio `&[hidden]`: la regla de base/_normalize.scss
   tiene la misma especificidad y va en una capa anterior, así que perdería. */
.admin-sugerido {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 0 14px;
  padding: 9px 14px;
  border-radius: 10px;
  background: #eefaf1;
  border: 1px solid #c7e9d3;
  font-size: 0.8rem;
  color: #15803d;
}
.admin-sugerido[hidden] {
  display: none;
}
.admin-sugerido::before {
  content: "\f058"; /* fa-circle-check */
  font-family: "Font Awesome 6 Free";
  font-weight: 900;
  font-size: 0.9rem;
}

/* Los 10 módulos se agrupan por las mismas 3 categorías del home y del sidebar:
   en una sola rejilla plana eran una lista indistinguible. */
.admin-modulos__cat + .admin-modulos__cat {
  margin-top: 18px;
}

.admin-modulos__cat-label {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 10px;
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--text-gray, #64748B);
}
.admin-modulos__cat-label i {
  color: var(--col-herencia, #4285f4);
}

/* =========================================================
   SWITCH ROW · interruptor con título y ayuda
   Componente compartido: "No puede suplir", "Mostrar en el calendario público", …
========================================================= */
.admin-switch-row {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 13px 16px;
  border: 1.5px solid #e2e8f0;
  border-radius: 14px;
  background: #fff;
  cursor: pointer;
  transition: border-color 0.18s ease, background 0.18s ease;
}
.admin-switch-row input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}
.admin-switch-row__track {
  position: relative;
  width: 44px;
  height: 25px;
  border-radius: 20px;
  background: #dde4ec;
  flex-shrink: 0;
  transition: background 0.2s ease;
}
.admin-switch-row__knob {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 19px;
  height: 19px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 1px 3px rgba(11, 31, 61, 0.3);
  transition: transform 0.2s cubic-bezier(0.34, 1.4, 0.64, 1);
}
.admin-switch-row__text {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.admin-switch-row__text strong {
  font-size: 13.5px;
  font-weight: 700;
  color: #1E293B;
  display: flex;
  align-items: center;
  gap: 7px;
}
.admin-switch-row__text small {
  font-size: 11.5px;
  color: #94A3B8;
  line-height: 1.45;
}
.admin-switch-row:hover {
  border-color: #c7d6ea;
}
.admin-switch-row input:checked ~ .admin-switch-row__track {
  background: #4267ac;
}
.admin-switch-row input:checked ~ .admin-switch-row__track .admin-switch-row__knob {
  transform: translateX(19px);
}
.admin-switch-row input:focus-visible ~ .admin-switch-row__track {
  outline: 2px solid #4267ac;
  outline-offset: 2px;
}
.admin-switch-row {
  /* Variante de exclusión (rojo): activarla es una restricción, no una mejora */
}
.admin-switch-row--danger strong i {
  color: #e51022;
}
.admin-switch-row--danger input:checked ~ .admin-switch-row__track {
  background: #e51022;
}
.admin-switch-row--danger:has(input:checked) {
  border-color: #f3c0c0;
  background: #fff6f6;
}
.admin-switch-row {
  /* Variante compacta: sin ayuda secundaria */
}
.admin-switch-row--compact {
  padding: 11px 14px;
}
.admin-switch-row--compact strong {
  font-size: 13px;
}

/* Bloque "No puede suplir" del formulario de usuarios (solo si es Profesor) */
.admin-suplir-toggle {
  margin-top: 14px;
}

.admin-suplir-toggle[hidden] {
  display: none;
}

/* Niveles que imparte un profesor. Van como pastillas y no como .admin-tipo-card: son
   cinco etiquetas de una palabra, y un tarjetón con icono + descripción ocuparía media
   pantalla para decir "Primaria". El color por nivel es el mismo del formulario de
   grupos (views/blog/grupos/_form.php).

   ⚠️ **COMPONENTE COMPARTIDO, no solo del formulario de usuarios.** Lo usa también
   «Niveles educativos» del formulario de eventos, que tuvo un clon propio
   (`.ev-niv__chip`) hasta que se borró: la misma pregunta se pintaba distinta en dos
   pantallas. Tocar esto toca las dos — `usuarios/crear|editar` y `eventos/crear|editar`. */
#niveles-group[hidden] {
  display: none;
}

.admin-niveles-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
}

.admin-nivel-check {
  cursor: pointer;
}
.admin-nivel-check input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.admin-nivel-check__box {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 9px 15px;
  border: 1.5px solid #e2e8f0;
  border-radius: 999px;
  background: #fff;
  font-size: 13px;
  font-weight: 600;
  color: #64748B;
  transition: border-color 0.18s ease, background 0.18s ease, color 0.18s ease;
}

/* ⚠️ MIDE LO MISMO MARCADO Y SIN MARCAR (16px), y no 10px que crecen a 11,5 con un
   `scale`. Es el hueco donde aparece el ✓, así que reservarlo siempre evita que la
   pastilla cambie de ancho al elegirla y reflúya la fila entera (§CLS). */
.admin-nivel-check__dot {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--c, #94a3b8);
  opacity: 0.35;
  font-size: 9px;
  color: #fff;
  transition: opacity 0.18s ease, background 0.18s ease;
}

.admin-nivel-check:hover .admin-nivel-check__box {
  border-color: #c7d6ea;
}

.admin-nivel-check:hover .admin-nivel-check__dot {
  opacity: 0.6;
}

.admin-nivel-check input:checked + .admin-nivel-check__box {
  border-color: var(--c, #4267ac);
  background: color-mix(in srgb, var(--c, #4267ac) 10%, #fff);
  color: #1E293B;
  font-weight: 700;
}

/* ⚠️ «ELEGIDO» NO PUEDE DEPENDER SOLO DEL COLOR. El borde y el velo al 10% son lo
   único que cambiaba, y en escala de grises eso es 1.09:1 (ámbar) contra el blanco:
   quien no distingue el tono no ve qué niveles ha marcado. El ✓ lo resuelve con la
   forma, igual que el badge de la esquina de `.admin-tipo-card`.
   El punto se oscurece al 70% con la tinta institucional porque el blanco sobre el
   ámbar puro se queda en 1.84:1 y sobre el lima en 2.01:1 — un ✓ es un gráfico con
   significado y necesita 3:1. Al 70% el peor caso da 3.33:1 y el tono se conserva. */
.admin-nivel-check input:checked + .admin-nivel-check__box .admin-nivel-check__dot {
  opacity: 1;
  background: color-mix(in srgb, var(--c, #4267ac) 70%, var(--pal-tinta, #0b1f3d));
}

.admin-nivel-check input:checked + .admin-nivel-check__box .admin-nivel-check__dot::before {
  content: "\f00c";
  font-family: "Font Awesome 6 Free";
  font-weight: 900;
  line-height: 1;
}

.admin-nivel-check input:focus-visible + .admin-nivel-check__box {
  outline: 2px solid var(--c, #4267ac);
  outline-offset: 2px;
}

/* ⚠️ 44px de objetivo táctil. Con `padding: 9px 15px` y 13px de texto la pastilla
   mide ~35px, y el panel se usa desde el móvil. Afecta a los dos consumidores, que
   es lo correcto: el problema lo tenían los dos. */
@media (max-width: 720px) {
  .admin-nivel-check__box {
    padding: 13px 16px;
  }
}
/* =========================================================
   FILE · zona de subida de archivos (justificantes, adjuntos)
   Compartido; el JS de src/js/admin/admin-file.js la activa por [data-file].
========================================================= */
.admin-file {
  position: relative;
  display: flex;
  align-items: center;
  gap: 13px;
  padding: 14px 16px;
  border: 1.5px dashed #cbd7e6;
  border-radius: 14px;
  background: #f9fbfe;
  cursor: pointer;
  transition: border-color 0.18s ease, background 0.18s ease;
  /* El input cubre la caja entera para que todo sea zona de clic */
}
.admin-file input[type=file] {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  cursor: pointer;
}
.admin-file__ico {
  width: 40px;
  height: 40px;
  border-radius: 11px;
  display: grid;
  place-items: center;
  background: #eef3fb;
  color: #4267ac;
  font-size: 15px;
  flex-shrink: 0;
  transition: background 0.18s ease, color 0.18s ease;
}
.admin-file__text {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.admin-file__title {
  font-size: 13.5px;
  font-weight: 700;
  color: #334155;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.admin-file__hint {
  font-size: 11.5px;
  color: #94A3B8;
}
.admin-file:hover {
  border-color: #4267ac;
