/* ── BÚSQUEDA ───────────────────────────────────────────── */
.noticias-search-wrap {
  margin-bottom: 20px;
}

.noticias-search-input-wrap {
  position: relative;
  max-width: 460px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.6);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border: 1.5px solid rgba(255, 255, 255, 0.75);
  box-shadow: 0 4px 20px rgba(77, 138, 187, 0.09), 0 1px 4px rgba(15, 23, 42, 0.06);
  transition: box-shadow 0.25s ease, border-color 0.25s ease;
}
.noticias-search-input-wrap:focus-within {
  border-color: rgba(77, 138, 187, 0.45);
  box-shadow: 0 0 0 4px rgba(77, 138, 187, 0.1), 0 4px 24px rgba(77, 138, 187, 0.12);
}
.noticias-search-input-wrap svg {
  position: absolute;
  left: 16px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--col-herencia);
  opacity: 0.75;
  pointer-events: none;
  z-index: 2;
  transition: opacity 0.2s;
}
.noticias-search-input-wrap:focus-within svg {
  opacity: 1;
  color: var(--col-bilbao);
}

.noticias-search-input {
  width: 100%;
  padding: 13px 20px 13px 44px;
  border: none;
  border-radius: 999px;
  font-size: 0.88rem;
  font-family: inherit;
  background: transparent;
  color: var(--col-texto);
  outline: none;
  appearance: none;
  -webkit-appearance: none;
}
.noticias-search-input::placeholder {
  color: var(--col-texto);
  opacity: 0.42;
}
.noticias-search-input::-webkit-search-cancel-button {
  -webkit-appearance: none;
  appearance: none;
}

/* ── FILTROS ────────────────────────────────────────────── */
.noticias-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 32px;
}

.noticias-filter-btn {
  padding: 9px 20px;
  border-radius: 999px;
  border: 1.5px solid var(--col-borde);
  background: #fff;
  font-size: 0.83rem;
  font-weight: 600;
  color: var(--col-texto);
  cursor: pointer;
  transition: all 0.22s ease;
  font-family: inherit;
}
.noticias-filter-btn:hover {
  background: #f1f5f9;
  border-color: rgba(77, 138, 187, 0.3);
}
.noticias-filter-btn.active {
  background: var(--col-herencia);
  border-color: var(--col-herencia);
  color: #fff;
  box-shadow: 0 4px 14px rgba(55, 76, 105, 0.18);
}
.noticias-filter-btn[data-noticia-filter=institucional].active {
  background: #2563eb;
  border-color: #2563eb;
}
.noticias-filter-btn[data-noticia-filter=academico].active {
  background: #7c3aed;
  border-color: #7c3aed;
}
.noticias-filter-btn[data-noticia-filter=cultural].active {
  background: #d97706;
  border-color: #d97706;
}
.noticias-filter-btn[data-noticia-filter=deportivo].active {
  background: #16a34a;
  border-color: #16a34a;
}
.noticias-filter-btn[data-noticia-filter=comunidad].active {
  background: #db2777;
  border-color: #db2777;
}

/* ── GRID ───────────────────────────────────────────────── */
.noticias-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 20px;
}
@media (min-width: 640px) {
  .noticias-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}
@media (min-width: 1100px) {
  .noticias-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

/* ── CARD — editorial vertical ──────────────────────────── */
.noticia-card {
  display: flex;
  flex-direction: column;
  background: rgba(255, 255, 255, 0.68);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border: 1px solid rgba(255, 255, 255, 0.55);
  border-radius: 20px;
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.06), 0 8px 28px rgba(55, 76, 105, 0.08);
  transition: transform 0.28s ease, box-shadow 0.28s ease, background 0.28s ease;
  position: relative;
  z-index: 1;
}
.noticia-card:hover {
  transform: translateY(-6px);
  background: rgba(255, 255, 255, 0.88);
  box-shadow: 0 4px 16px rgba(15, 23, 42, 0.08), 0 20px 52px rgba(55, 76, 105, 0.14);
}
.noticia-card:hover .noticia-card-title a {
  color: var(--col-bilbao);
}
.noticia-card:hover .noticia-card-img img {
  transform: scale(1.04);
}
.noticia-card.is-hidden {
  display: none;
}

.noticia-card-img {
  display: block;
  position: relative;
  aspect-ratio: 16/9;
  overflow: hidden;
  flex-shrink: 0;
  text-decoration: none;
}
.noticia-card-img img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.4s ease;
  user-select: none;
}
.noticia-card-img .cat-chip {
  position: absolute;
  top: 12px;
  left: 12px;
  z-index: 2;
  background: rgba(255, 255, 255, 0.18) !important;
  color: #fff !important;
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border: 1px solid rgba(255, 255, 255, 0.32);
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.28);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
}
.noticia-card-img.noticia-card-img--empty {
  display: flex;
  align-items: center;
  justify-content: center;
}
.noticia-card-img.noticia-card-img--mascot img {
  object-fit: contain;
  padding: 16px;
  height: 80%;
  width: auto;
}

/* Fondo sólido para cards sin portada — permite que el glassmorphism del card sea visible */
.noticia-card-img--empty {
  background: linear-gradient(140deg, #0d2451 0%, #1a4a9f 55%, #1d5ab0 100%);
  border-bottom: 1px solid rgba(30, 80, 180, 0.25);
}

/* Variantes de color por categoría (chip visible sobre el fondo azul) */
.cat-bg-institucional,
.cat-bg-academico,
.cat-bg-cultural,
.cat-bg-deportivo,
.cat-bg-comunidad { /* heredan el fondo azul de --empty */ }

.noticia-nueva-dot {
  position: absolute;
  top: 12px;
  right: 12px;
  z-index: 2;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #ef4444;
  border: 2px solid #fff;
  box-shadow: 0 2px 6px rgba(239, 68, 68, 0.4);
}

.noticia-card-body {
  flex: 1;
  padding: 18px 20px 20px;
  display: flex;
  flex-direction: column;
  background: transparent;
}

.noticia-card-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 10px;
}

.noticia-date {
  font-size: 0.74rem;
  font-weight: 600;
  color: var(--col-texto);
  opacity: 0.48;
  white-space: nowrap;
}

.noticia-freshness {
  font-size: 0.72rem;
  color: var(--col-texto);
  opacity: 0.38;
  white-space: nowrap;
  flex-shrink: 0;
}

.noticia-card-title {
  font-size: 1.06rem;
  line-height: 1.3;
  color: var(--col-herencia);
  margin-bottom: 10px;
  letter-spacing: -0.02em;
  flex: 1;
}
.noticia-card-title a {
  color: inherit;
  text-decoration: none;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
  transition: color 0.2s ease;
}

.noticia-card-excerpt {
  font-size: 0.84rem;
  font-weight: 300;
  color: var(--col-texto);
  opacity: 0.72;
  line-height: 1.65;
  margin-bottom: 16px;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.noticia-read-more {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--col-bilbao);
  text-decoration: none;
  transition: gap 0.2s ease, color 0.2s ease;
  margin-top: auto;
}
.noticia-read-more:hover {
  color: var(--col-herencia);
  gap: 10px;
}

/* ── Autor en card ──────────────────────────────────────── */
.noticia-card-author {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid var(--col-borde);
  flex-shrink: 0;
}

.noticia-card-author-avatar {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--col-herencia), var(--col-bilbao));
  color: #fff;
  font-size: 0.62rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  overflow: hidden;
}
.noticia-card-author-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 50%;
}

.noticia-card-author-name {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--col-texto);
  opacity: 0.55;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ── EMPTY STATE ────────────────────────────────────────── */
.noticias-empty {
  display: none;
  padding: 52px 24px;
  text-align: center;
  background: #fff;
  border: 1px solid var(--col-borde);
  border-radius: 24px;
  color: var(--col-texto);
}
.noticias-empty img {
  width: 100px;
  margin: 0 auto 20px;
  display: block;
  opacity: 0.4;
  filter: grayscale(0.4);
}
.noticias-empty h3 {
  font-size: 1.3rem;
  margin-bottom: 8px;
  color: var(--col-herencia);
}
.noticias-empty p {
  font-size: 0.9rem;
  opacity: 0.6;
}
.noticias-empty.show {
  display: block;
}

/* ── CTA ────────────────────────────────────────────────── */
.noticias-cta {
  padding: 0 24px 100px;
}

.noticias-cta-box {
  background: linear-gradient(135deg, var(--col-herencia) 0%, #1a4a9f 50%, var(--col-bilbao) 100%);
  color: #fff;
  border-radius: 28px;
  padding: 52px 32px;
  text-align: center;
  box-shadow: 0 28px 60px rgba(15, 23, 42, 0.2);
  position: relative;
  overflow: hidden;
}
.noticias-cta-box::before {
  content: "";
  position: absolute;
  top: -40%;
  right: -8%;
  width: 55%;
  height: 200%;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.05), transparent 68%);
  pointer-events: none;
}
.noticias-cta-box h3 {
  font-size: clamp(1.8rem, 4vw, 2.4rem);
  margin-bottom: 14px;
  letter-spacing: -0.03em;
}
.noticias-cta-box p {
  max-width: 620px;
  margin: 0 auto 28px;
  font-size: 0.95rem;
  font-weight: 300;
  line-height: 1.75;
  opacity: 0.9;
}
.noticias-cta-box .btn-terciario {
  font-size: 0.875rem;
  padding: 12px 30px;
}

/* ═══════════════════════════════════════════════════════
   DETALLE
═══════════════════════════════════════════════════════ */
.read-progress-bar {
  position: fixed;
  top: 0;
  left: 0;
  height: 3px;
  width: 0%;
  background: linear-gradient(90deg, var(--col-bilbao), var(--col-espiritu));
  z-index: 9999;
  border-radius: 0 2px 2px 0;
  transition: width 0.08s linear;
  pointer-events: none;
}

.noticia-detalle {
  background: #fff;
}

/* ── Hero portada full-width ────────────────────────────── */
.nd-hero-portada {
  position: relative;
  height: max(78vh, 520px);
  width: 100%;
  overflow: hidden;
  display: flex;
  align-items: flex-end;
}
.nd-hero-portada--empty {
  background: linear-gradient(145deg, var(--col-herencia) 0%, #1a2d4f 50%, #0f1e38 100%);
}

.nd-hero-portada-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 115%;
  object-fit: cover;
  object-position: center 30%;
  z-index: 0;
  will-change: transform;
}
.nd-hero-portada-img--placeholder {
  opacity: 0.35;
  object-position: center;
}

.nd-hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(5, 15, 40, 0.95) 0%, rgba(10, 25, 65, 0.72) 40%, rgba(0, 0, 0, 0.12) 100%), linear-gradient(to right, rgba(0, 0, 0, 0.18) 0%, transparent 70%);
  z-index: 1;
}

.nd-hero-portada--empty .nd-hero-overlay {
  background: linear-gradient(to top, rgba(5, 15, 40, 0.75) 0%, rgba(10, 25, 65, 0.5) 40%, rgba(0, 0, 0, 0.06) 100%), linear-gradient(to right, rgba(0, 0, 0, 0.1) 0%, transparent 70%);
}

.nd-hero-alex {
  position: absolute;
  bottom: 0;
  right: clamp(24px, 5vw, 80px);
  width: clamp(110px, 14vw, 210px);
  z-index: 3;
  filter: drop-shadow(0 20px 36px rgba(0, 0, 0, 0.45));
  animation: mascot-float 3.6s ease-in-out infinite;
  pointer-events: none;
}
@media (max-width: 640px) {
  .nd-hero-alex {
    width: 80px;
    right: 12px;
    opacity: 0.45;
  }
}

.nd-hero-content {
  position: relative;
  z-index: 2;
  width: 100%;
  padding: 0 0 36px;
}
.nd-hero-content .container {
  max-width: 900px;
  padding-bottom: 16px;
}

.nd-hero-glass-card {
  background: transparent;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  border: none;
  border-top: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 0;
  padding: 24px 0 0;
}
@media (max-width: 640px) {
  .nd-hero-glass-card {
    padding: 18px 0 0;
  }
}

.nd-hero-meta {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 18px;
  animation: fadeInUp 0.8s cubic-bezier(0.2, 0.8, 0.2, 1) 0.05s backwards;
}

.nd-hero-date {
  font-size: 0.8rem;
  color: rgba(255, 255, 255, 0.55);
}

.nd-hero-title {
  font-size: clamp(1.9rem, 4.8vw, 3.6rem);
  line-height: 1.04;
  letter-spacing: -0.04em;
  color: #fff;
  margin-bottom: 16px;
  max-width: 760px;
  text-shadow: 0 4px 24px rgba(0, 0, 0, 0.25);
  animation: fadeInUp 0.85s cubic-bezier(0.2, 0.8, 0.2, 1) 0.1s backwards;
}

.nd-hero-lead {
  font-size: clamp(0.95rem, 1.5vw, 1.08rem);
  font-weight: 300;
  line-height: 1.78;
  color: rgba(255, 255, 255, 0.82);
  max-width: 620px;
  margin-bottom: 28px;
  animation: fadeInUp 0.9s cubic-bezier(0.2, 0.8, 0.2, 1) 0.15s backwards;
}

.nd-hero-byline {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
  padding-top: 20px;
  border-top: 1px solid rgba(255, 255, 255, 0.15);
  animation: fadeInUp 0.95s cubic-bezier(0.2, 0.8, 0.2, 1) 0.2s backwards;
}

.nd-author-wrap {
  display: flex;
  align-items: center;
  gap: 12px;
  flex: 1;
  min-width: 0;
}

.nd-author-avatar {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--col-herencia), var(--col-bilbao));
  border: 2px solid rgba(255, 255, 255, 0.28);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 0.74rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  flex-shrink: 0;
  overflow: hidden;
}
.nd-author-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 50%;
}

.nd-author-meta {
  min-width: 0;
}
.nd-author-meta strong {
  display: block;
  font-size: 0.9rem;
  color: #fff;
  font-weight: 700;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.nd-author-meta span {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
  font-size: 0.78rem;
  color: rgba(255, 255, 255, 0.52);
  line-height: 1.5;
}

.nd-sep {
  opacity: 0.35;
  font-size: 0.65rem;
}

.nd-hero-share {
  display: flex;
  gap: 8px;
  flex-shrink: 0;
}
@media (max-width: 480px) {
  .nd-hero-share {
    width: 100%;
  }
}

.nd-share-btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 0.8rem;
  font-weight: 700;
  padding: 10px 18px;
  border-radius: 999px;
  border: 1.5px solid rgba(255, 255, 255, 0.45);
  background: rgba(255, 255, 255, 0.18);
  color: #fff;
  cursor: pointer;
  font-family: inherit;
  text-decoration: none;
  transition: background 0.22s ease, border-color 0.22s ease, transform 0.18s ease;
  white-space: nowrap;
  line-height: 1;
}
.nd-share-btn:hover {
  background: rgba(255, 255, 255, 0.28);
  border-color: rgba(255, 255, 255, 0.65);
  transform: translateY(-1px);
}
.nd-share-btn--wa {
  background: #25d366;
  border-color: #25d366;
}
.nd-share-btn--wa:hover {
  background: #1da851;
  border-color: #1da851;
}

/* ── Nav / Breadcrumb ───────────────────────────────────── */
.noticia-detalle-nav {
  padding: 22px 24px 0;
  display: flex;
  align-items: center;
  gap: 8px;
}
.noticia-detalle-nav a {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--col-bilbao);
  text-decoration: none;
  transition: color 0.2s ease;
}
.noticia-detalle-nav a svg {
  transition: transform 0.2s ease;
}
.noticia-detalle-nav a:hover {
  color: var(--col-herencia);
}
.noticia-detalle-nav a:hover svg {
  transform: translateX(-3px);
}

.nd-breadcrumb-divider {
  color: var(--col-texto);
  opacity: 0.25;
  font-size: 0.8rem;
}

.nd-breadcrumb-current {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--col-texto);
  opacity: 0.5;
}

/* ── Alex summary ───────────────────────────────────────── */
.alex-summary {
  max-width: 720px;
  margin: 36px auto 0;
  padding: 0 24px;
}

.alex-summary-inner {
  display: flex;
  align-items: flex-start;
  gap: 16px;
}

.alex-summary-mascot-wrap {
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  padding-top: 4px;
}
.alex-summary-mascot-wrap img {
  width: 64px;
  filter: drop-shadow(0 5px 12px rgba(0, 0, 0, 0.1));
  animation: mascot-float 3.8s ease-in-out infinite;
}
.alex-summary-mascot-wrap span {
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--col-bilbao);
  opacity: 0.7;
}

.alex-summary-bubble {
  background: #fff;
  border: 1.5px solid rgba(77, 138, 187, 0.18);
  border-radius: 20px 20px 20px 4px;
  padding: 20px 24px;
  flex: 1;
  box-shadow: 0 6px 24px rgba(77, 138, 187, 0.08);
}
.alex-summary-bubble .summary-label {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 0.69rem;
  font-weight: 700;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--col-bilbao);
  margin-bottom: 10px;
}
.alex-summary-bubble .summary-label::before {
  content: "";
  width: 18px;
  height: 2px;
  background: var(--col-bilbao);
  border-radius: 1px;
}
.alex-summary-bubble p {
  font-size: 0.97rem;
  line-height: 1.72;
  color: var(--col-herencia);
  font-weight: 400;
  margin: 0;
}
.alex-summary-bubble p strong {
  color: var(--col-bilbao);
}

/* ── TOC ────────────────────────────────────────────────── */
.noticia-toc {
  max-width: 720px;
  margin: 28px auto 0;
  padding: 0 24px;
}

.noticia-toc-inner {
  background: linear-gradient(135deg, #f8fafc, #eff6ff);
  border: 1px solid rgba(77, 138, 187, 0.14);
  border-radius: 22px;
  padding: 22px 28px;
  display: flex;
  align-items: center;
  gap: 20px;
  position: relative;
  overflow: hidden;
}
.noticia-toc-inner::before {
  content: "";
  position: absolute;
  top: -50%;
  right: -10%;
  width: 40%;
  height: 200%;
  background: radial-gradient(circle, rgba(77, 138, 187, 0.05), transparent 65%);
  pointer-events: none;
}

.noticia-toc-alex {
  flex-shrink: 0;
  width: 68px;
  filter: drop-shadow(0 4px 10px rgba(0, 0, 0, 0.1));
}
@media (max-width: 480px) {
  .noticia-toc-alex {
    display: none;
  }
}

.noticia-toc-body {
  flex: 1;
}
.noticia-toc-body h4 {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--col-bilbao);
  margin-bottom: 14px;
}
.noticia-toc-body h4::after {
  content: "";
  flex: 1;
  height: 1px;
  background: rgba(77, 138, 187, 0.2);
}
.noticia-toc-body ol {
  list-style: none;
  padding: 0;
  margin: 0;
  counter-reset: toc-counter;
  display: flex;
  flex-direction: column;
  gap: 7px;
}
.noticia-toc-body li {
  counter-increment: toc-counter;
}
.noticia-toc-body a {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--col-herencia);
