}
.noticia-toc-body a::before {
  content: counter(toc-counter, decimal-leading-zero);
  font-size: 0.68rem;
  font-weight: 700;
  color: var(--col-bilbao);
  opacity: 0.55;
  width: 22px;
  flex-shrink: 0;
}
.noticia-toc-body a:hover {
  color: var(--col-bilbao);
  padding-left: 4px;
}

/* ── Cuerpo del artículo ────────────────────────────────── */
.noticia-detalle-body {
  max-width: 720px;
  margin: 36px auto 0;
  padding: 0 24px;
}
.noticia-detalle-body h2 {
  font-size: clamp(1.45rem, 3vw, 1.85rem);
  font-weight: 800;
  color: var(--col-herencia);
  margin: 52px 0 18px;
  letter-spacing: -0.03em;
  line-height: 1.2;
  scroll-margin-top: 96px;
}
.noticia-detalle-body h2:first-child {
  margin-top: 0;
}
.noticia-detalle-body h3 {
  font-size: 1.4rem;
  color: var(--col-herencia);
  margin: 44px 0 16px;
  letter-spacing: -0.03em;
  padding-left: 16px;
  border-left: 3px solid var(--col-bilbao);
}
.noticia-detalle-body p {
  font-size: 0.88rem;
  line-height: 1.82;
  color: var(--col-texto);
  margin-bottom: 20px;
  font-weight: 400;
}
.noticia-detalle-body ul {
  margin: 0 0 28px;
  list-style: none;
  padding: 0;
}
.noticia-detalle-body ul li {
  font-size: 0.95rem;
  line-height: 1.8;
  color: var(--col-texto);
  font-weight: 400;
  margin-bottom: 10px;
  padding-left: 24px;
  position: relative;
}
.noticia-detalle-body ul li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.68em;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--col-bilbao);
  opacity: 0.6;
}
.noticia-detalle-body blockquote {
  margin: 44px 0;
  padding: 28px 32px;
  background: linear-gradient(135deg, rgba(77, 138, 187, 0.04), rgba(125, 198, 229, 0.03));
  border-left: 5px solid var(--col-bilbao);
  border-radius: 0 20px 20px 0;
  position: relative;
}
.noticia-detalle-body blockquote::before {
  content: '"';
  position: absolute;
  top: -8px;
  left: 28px;
  font-size: 5rem;
  line-height: 1;
  color: var(--col-bilbao);
  opacity: 0.15;
  font-weight: 900;
}
.noticia-detalle-body blockquote p {
  font-size: 1.2rem;
  font-weight: 400;
  font-style: italic;
  opacity: 0.92;
  margin-bottom: 12px;
  line-height: 1.7;
}
.noticia-detalle-body blockquote cite {
  font-size: 0.85rem;
  font-style: normal;
  opacity: 0.48;
  color: var(--col-texto);
}

/* Drop cap primer bloque — targeting both <p> and <div> (contenteditable default) */
.noticia-detalle-body--lead > p:first-of-type::first-letter,
.noticia-detalle-body--lead > div:first-child::first-letter {
  float: left;
  font-size: 3.6rem;
  line-height: 0.82;
  font-weight: 900;
  color: var(--col-bilbao);
  margin-right: 8px;
  margin-top: 5px;
  letter-spacing: -0.03em;
}

/* ── Alex callout ───────────────────────────────────────── */
.alex-callout {
  max-width: 720px;
  margin: 44px auto;
  padding: 0 24px;
}
.alex-callout > div {
  background: linear-gradient(135deg, #eff6ff 0%, #f0fdf4 100%);
  border: 1px solid rgba(77, 138, 187, 0.18);
  border-radius: 22px;
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 24px 28px;
  overflow: hidden;
}

.alex-callout--pregunta > div {
  background: linear-gradient(135deg, #fff7ed, #fef3c7);
  border-color: rgba(217, 119, 6, 0.2);
}
.alex-callout--pregunta > div .callout-label--pregunta {
  color: #d97706;
}
.alex-callout--pregunta > div .callout-label--pregunta::before {
  background: #d97706;
}
.alex-callout--pregunta > div p strong {
  color: #d97706;
}

.alex-callout-mascot {
  flex-shrink: 0;
  width: 80px;
  filter: drop-shadow(0 6px 12px rgba(0, 0, 0, 0.1));
  animation: mascot-float 3.2s ease-in-out infinite;
}

.alex-callout-content {
  flex: 1;
}
.alex-callout-content .callout-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--col-bilbao);
  margin-bottom: 8px;
}
.alex-callout-content .callout-label::before {
  content: "";
  width: 18px;
  height: 2px;
  background: var(--col-bilbao);
  border-radius: 1px;
}
.alex-callout-content p {
  font-size: 1rem;
  font-weight: 400;
  color: var(--col-herencia);
  line-height: 1.65;
  margin: 0;
}
.alex-callout-content p strong {
  color: var(--col-bilbao);
}

/* ── Key stats ──────────────────────────────────────────── */
.noticia-key-stats {
  max-width: 720px;
  margin: 44px auto;
  padding: 0 24px;
}

.key-stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
}
@media (max-width: 500px) {
  .key-stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

.key-stat-item {
  background: #fff;
  border: 1px solid var(--col-borde);
  border-radius: 18px;
  padding: 22px 16px;
  text-align: center;
  position: relative;
  overflow: hidden;
  transition: transform 0.26s ease, box-shadow 0.26s ease;
}
.key-stat-item::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--stat-color, var(--col-bilbao));
