  font-weight: 900;
  letter-spacing: -0.06em;
  line-height: 1;
  color: var(--stat-color, var(--col-bilbao));
  margin-bottom: 7px;
  font-variant-numeric: tabular-nums;
}

.key-stat-label {
  font-size: 0.76rem;
  font-weight: 600;
  color: var(--col-texto);
  opacity: 0.6;
  line-height: 1.45;
}

/* ── Pull quote ─────────────────────────────────────────── */
.noticia-pull-quote {
  max-width: 720px;
  margin: 52px auto;
  padding: 0 24px;
}

.pull-quote-inner {
  background: linear-gradient(140deg, var(--col-herencia) 0%, #1a4a9f 55%, var(--col-bilbao) 100%);
  border-radius: 26px;
