}
.pull-quote-inner::before {
  content: '"';
  position: absolute;
  top: -28px;
  right: 18px;
  font-size: 14rem;
  line-height: 1;
  color: rgba(255, 255, 255, 0.05);
  font-weight: 900;
  pointer-events: none;
  user-select: none;
}
@media (max-width: 480px) {
  .pull-quote-inner {
    padding: 28px 24px;
  }
}

.pull-quote-text {
  font-size: clamp(1.1rem, 2.2vw, 1.5rem);
  font-weight: 700;
  line-height: 1.52;
  letter-spacing: -0.025em;
  margin-bottom: 22px;
  position: relative;
  z-index: 1;
}

.pull-quote-source {
  display: flex;
  align-items: center;
  gap: 12px;
}
.pull-quote-source .source-name {
  font-size: 0.88rem;
  font-weight: 700;
  opacity: 0.9;
  display: block;
}
.pull-quote-source .source-role {
  font-size: 0.76rem;
