}
.noticia-tags .tags-label {
  font-size: 0.73rem;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--col-texto);
  opacity: 0.38;
  flex-shrink: 0;
  margin-right: 2px;
}

.noticia-tag {
  display: inline-flex;
  align-items: center;
  padding: 6px 14px;
  border-radius: 999px;
  background: #f1f5f9;
  color: var(--col-texto);
