}

/* ── Celebración fin de lectura ─────────────────────────── */
.noticia-celebration {
  max-width: 720px;
  margin: 64px auto 0;
  padding: 0 24px;
}

.celebration-inner {
  background: linear-gradient(140deg, #0a1f4e 0%, #1a3b82 55%, #0f6fdf 100%);
  border-radius: 28px;
  padding: 48px 32px;
  text-align: center;
  position: relative;
  overflow: hidden;
  color: #fff;
  box-shadow: 0 36px 72px rgba(10, 31, 78, 0.32);
}
.celebration-inner::before {
  content: "";
  position: absolute;
  top: -20%;
  left: -5%;
  width: 40%;
  height: 180%;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.06), transparent 60%);
  pointer-events: none;
}

.celebration-mascot-group {
  position: relative;
  display: inline-block;
  margin-bottom: 22px;
}

.celebration-mascot {
  width: 100px;
  filter: drop-shadow(0 12px 24px rgba(0, 0, 0, 0.38));
  animation: celebration-bounce 0.65s ease-in-out infinite alternate;
  position: relative;
  z-index: 2;
}

.celebration-confetti {
  position: absolute;
  inset: -30px;
  pointer-events: none;
  overflow: visible;
}
.celebration-confetti .confetti-piece {
  position: absolute;
  width: 8px;
  height: 8px;
  border-radius: 2px;
  opacity: 0;
}
.celebration-confetti .confetti-piece:nth-child(1) {
  left: 10%;
  top: 5%;
  background: #ef4444;
  animation: confetti-fall 2.2s ease 0s infinite;
}
.celebration-confetti .confetti-piece:nth-child(2) {
  left: 28%;
  top: 0%;
  background: #f59e0b;
  animation: confetti-fall 1.9s ease 0.3s infinite;
  width: 6px;
  height: 11px;
}
.celebration-confetti .confetti-piece:nth-child(3) {
  left: 50%;
  top: 3%;
  background: #10b981;
  animation: confetti-fall 2.4s ease 0.1s infinite;
  border-radius: 50%;
}
.celebration-confetti .confetti-piece:nth-child(4) {
  left: 72%;
  top: 1%;
  background: #6366f1;
  animation: confetti-fall 2.1s ease 0.5s infinite;
}
.celebration-confetti .confetti-piece:nth-child(5) {
  left: 88%;
  top: 8%;
  background: #ec4899;
  animation: confetti-fall 1.8s ease 0.2s infinite;
  width: 10px;
  height: 5px;
}
.celebration-confetti .confetti-piece:nth-child(6) {
  left: 18%;
  top: 15%;
  background: #0ea5e9;
  animation: confetti-fall 2.3s ease 0.4s infinite;
  border-radius: 50%;
  width: 5px;
  height: 5px;
}
.celebration-confetti .confetti-piece:nth-child(7) {
  left: 62%;
  top: 10%;
  background: #f97316;
  animation: confetti-fall 2s ease 0.6s infinite;
}
.celebration-confetti .confetti-piece:nth-child(8) {
  left: 40%;
  top: 18%;
  background: #84cc16;
  animation: confetti-fall 2.5s ease 0.15s infinite;
  border-radius: 50%;
  width: 6px;
  height: 6px;
}

@keyframes confetti-fall {
  0% {
    opacity: 0;
    transform: translateY(-24px) rotate(0deg) scale(0.8);
  }
  12% {
    opacity: 1;
  }
  80% {
    opacity: 0.6;
  }
  100% {
    opacity: 0;
    transform: translateY(72px) rotate(400deg) scale(1.1);
  }
}
@keyframes celebration-bounce {
  0% {
    transform: translateY(0) rotate(-4deg);
  }
  100% {
    transform: translateY(-12px) rotate(4deg);
  }
}
.celebration-title {
  font-size: clamp(1.5rem, 3.5vw, 2rem);
  font-weight: 900;
  letter-spacing: -0.03em;
  margin-bottom: 8px;
}

.celebration-subtitle {
  font-size: 0.9rem;
  font-weight: 300;
  opacity: 0.75;
  margin-bottom: 28px;
  line-height: 1.65;
  max-width: 460px;
  margin-left: auto;
  margin-right: auto;
}

.celebration-actions {
  display: flex;
  gap: 10px;
  justify-content: center;
  flex-wrap: wrap;
}

.celebration-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 0.84rem;
  font-weight: 700;
  padding: 12px 22px;
  border-radius: 999px;
  cursor: pointer;
  font-family: inherit;
  text-decoration: none;
  transition: all 0.22s ease;
  border: none;
  line-height: 1;
}
.celebration-btn--copy {
  background: rgba(255, 255, 255, 0.13);
  color: #fff;
  border: 1.5px solid rgba(255, 255, 255, 0.24);
}
.celebration-btn--copy:hover {
  background: rgba(255, 255, 255, 0.22);
}
.celebration-btn--wa {
  background: #25d366;
  color: #fff;
}
.celebration-btn--wa:hover {
  background: #1da851;
}
.celebration-btn--back {
  background: #fff;
  color: var(--col-herencia);
}
.celebration-btn--back:hover {
  background: #eff6ff;
  color: var(--col-bilbao);
}

/* ── Companion flotante ─────────────────────────────────── */
.read-companion {
  position: fixed;
  bottom: 28px;
  right: 22px;
  display: flex;
  align-items: flex-end;
  gap: 10px;
  z-index: 200;
  opacity: 0;
  transform: translateY(16px);
  transition: opacity 0.4s ease, transform 0.4s ease;
  pointer-events: none;
}
.read-companion.show {
  opacity: 1;
  transform: translateY(0);
  pointer-events: all;
}

.read-companion-mascot {
  width: 56px;
  filter: drop-shadow(0 6px 14px rgba(0, 0, 0, 0.22));
  flex-shrink: 0;
}

.read-companion-bubble {
  background: #fff;
  border: 1.5px solid var(--col-borde);
  border-radius: 16px 16px 4px 16px;
  padding: 10px 16px;
  box-shadow: 0 10px 28px rgba(15, 23, 42, 0.12);
  font-size: 0.84rem;
  font-weight: 600;
  color: var(--col-herencia);
  white-space: nowrap;
  position: relative;
}
.read-companion-bubble::after {
  content: "";
  position: absolute;
  bottom: -8px;
  right: 18px;
  width: 14px;
  height: 8px;
  background: #fff;
  clip-path: polygon(0 0, 100% 0, 50% 100%);
}

/* ── Noticias relacionadas ──────────────────────────────── */
.noticia-relacionadas {
