  /* ── HERO ─────────────────────────────────── */
}
.fam__hero {
  position: relative;
  /* Claro del bosque: cielo profundo arriba, bruma teal, destello de sol cálido */
  background: radial-gradient(60% 80% at 78% 6%, rgba(241, 196, 0, 0.18), transparent 46%), radial-gradient(90% 120% at 88% 20%, rgba(70, 189, 198, 0.26), transparent 50%), radial-gradient(120% 90% at 10% 100%, rgba(36, 80, 111, 0.55), transparent 60%), linear-gradient(180deg, #071528 0%, #0d2b3f 50%, #103a48 100%);
  border-bottom: 1px solid var(--col-borde);
  overflow: hidden;
}
.fam .comunidad-bg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 0;
  pointer-events: none;
}
.fam__hero-inner {
  position: relative;
  z-index: 1;
  max-width: 1120px;
  margin: 0 auto;
  padding: 60px 24px 66px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
  text-align: left;
}
.fam__hero-chips {
  display: flex;
  gap: 10px;
  margin-top: 22px;
}
.fam__chip {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 8px 16px;
  border-radius: 100px;
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid rgba(255, 255, 255, 0.2);
