}
.fam {
  /* ── SECCIONES ────────────────────────────── */
}
.fam__section {
  max-width: 1140px;
  margin: 0 auto;
  padding: 56px 24px;
}
.fam__section--cal {
  padding-bottom: 88px;
}
.fam__section-head {
  text-align: center;
  margin-bottom: 36px;
}
.fam__section-title {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  font-size: 1.7rem;
  font-weight: 900;
  color: var(--col-bilbao);
  margin-bottom: 8px;
}
.fam__section-title i {
  color: #fc6722;
}
.fam__section-sub {
  font-size: 0.98rem;
