  box-shadow: 0 20px 40px -20px rgba(22, 32, 46, 0.4);
}
.fam-aviso__date {
  flex-shrink: 0;
  width: 62px;
  height: 62px;
  border-radius: 18px;
  background: var(--aviso-color, var(--col-bilbao));
  color: #fff;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  line-height: 1;
}
.fam-aviso__day {
  font-size: 1.55rem;
  font-weight: 900;
}
.fam-aviso__month {
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  opacity: 0.9;
}
.fam-aviso__pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 11px;
  border-radius: 100px;
  background: color-mix(in srgb, var(--aviso-color) 14%, #fff);
