.mh-card--c4 {
  background: linear-gradient(145deg, #75156a 0%, #aa2296 100%);
} /* morado        */
.mh-card--c5 {
  background: linear-gradient(145deg, #a80440 0%, #ea075a 100%);
} /* rosa          */
.mh-card--c6 {
  background: linear-gradient(145deg, #a80c1a 0%, #e51022 100%);
} /* rojo          */
.mh-card--c7 {
  background: linear-gradient(145deg, #c74b12 0%, #fc6722 100%);
