body[data-page=blog-usuarios-horario] .hed-grid__hour-time {
  display: block;
  font-size: 0.68rem;
  font-weight: 600;
  color: #94a3b8;
  font-variant-numeric: tabular-nums;
}
body[data-page=blog-usuarios-horario] .hed-grid__receso-row .hed-grid__hour-label {
  font-size: 0.74rem;
  color: #a16207;
}
body[data-page=blog-usuarios-horario] {
  /* ── Casillas ──
     El contenido se ancla al <td> con position:absolute porque en una tabla
     `height` es un mínimo y un height:100% del hijo no resuelve bien. */
}
body[data-page=blog-usuarios-horario] .hed-cell > .hed-libre, body[data-page=blog-usuarios-horario] .hed-cell > .hed-block, body[data-page=blog-usuarios-horario] .hed-cell > .hed-ajena {
  position: absolute;
  inset: 0;
}
body[data-page=blog-usuarios-horario] {
  /* Libre: pulsar abre el modal de clase */
