  }
  body[data-page=blog-personal-index] .per-table tbody tr.is-hidden,
  body[data-page=blog-personal-index] .per-table tbody tr.is-filtered {
    display: none;
  }
  body[data-page=blog-personal-index] .per-table tbody td {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 14px;
    padding: 5px 0;
    border: 0;
    text-align: right;
    /* #64748B y no #94a3b8: aquel da 2,56:1 sobre blanco y no pasa AA a
       .74rem, y esta etiqueta es lo único que dice qué es cada dato de la
       tarjeta. Peso 700 para no competir con el nombre, que va a 800. */
  }
  body[data-page=blog-personal-index] .per-table tbody td::before {
    content: attr(data-label);
    flex-shrink: 0;
    font-size: 0.74rem;
    font-weight: 700;
    color: #64748B;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    text-align: left;
  }
  body[data-page=blog-personal-index] .per-table {
    /* El colaborador es la cabecera de la tarjeta, no una fila más: sin etiqueta,
       a ancho completo y con el avatar delante. */
  }
  body[data-page=blog-personal-index] .per-table tbody td:first-child {
    display: block;
    padding-bottom: 10px;
    margin-bottom: 4px;
    border-bottom: 1px solid #f1f5f9;
    text-align: left;
  }
  body[data-page=blog-personal-index] .per-table tbody td:first-child::before {
    content: none;
  }
  body[data-page=blog-personal-index] .per-table {
    /* Los chips y las acciones se alinean a la derecha, con su etiqueta a la
       izquierda: si envuelven, lo hacen sin descolgarse de la fila. */
  }
  body[data-page=blog-personal-index] .per-table .per-nivel,
  body[data-page=blog-personal-index] .per-table .admin-badge {
    margin-left: 2px;
  }
  body[data-page=blog-personal-index] .per-table .admin-table__actions {
    justify-content: flex-end;
    flex-wrap: wrap;
  }
  body[data-page=blog-personal-index] .per-table .per-mail {
    word-break: break-all;
  }
}

